def create_draft(raw=None, threadId=None, to=None, cc=None, bcc=None, subject=None, body=None, includeBodyHtml=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0088000" if __import__("os").path.isdir("./environment_mix/0088000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, gmail_account_id=None, error_code=None, error_message=None):
        logs = _load("gmail_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"grl_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "create_draft",
            "gmail_account_id": gmail_account_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        })
        _save("gmail_request_logs.json", logs)

    def _resolve_account():
        accts = _load("gmail_accounts.json")
        if not isinstance(accts, list):
            return None
        # Prefer active then suspended; never choose disconnected.
        for st in ("active", "suspended"):
            for a in accts:
                if isinstance(a, dict) and a.get("status") == st and a.get("id"):
                    return a
        for a in accts:
            if isinstance(a, dict) and a.get("status") != "disconnected" and a.get("id"):
                return a
        return None

    def _is_list_of_str(x):
        if x is None:
            return True
        if not isinstance(x, list):
            return False
        return all(isinstance(i, str) for i in x)

    def _looks_like_base64url(s):
        # Relaxed: accept any non-empty string comprised of urlsafe base64 chars and optional '=' padding.
        # Do NOT reject non-base64 payloads too aggressively; provider would validate, but local store should accept.
        if not isinstance(s, str) or not s.strip():
            return False
        return re.fullmatch(r"[A-Za-z0-9\-_]+=*", s.strip()) is not None

    acct = _resolve_account()
    if not acct:
        _log("error", None, "UNAUTHORIZED", "No authenticated Gmail account context available.")
        return _err("UNAUTHORIZED", "No authenticated Gmail account context available.")
    gmail_account_id = acct["id"]

    # Validate parameter types (per schema: everything optional)
    if raw is not None and not isinstance(raw, str):
        _log("error", gmail_account_id, "VALIDATION_ERROR", "raw must be a string when provided.")
        return _err("VALIDATION_ERROR", "raw must be a string when provided.", field="raw")
    if threadId is not None and not isinstance(threadId, str):
        _log("error", gmail_account_id, "VALIDATION_ERROR", "threadId must be a string when provided.")
        return _err("VALIDATION_ERROR", "threadId must be a string when provided.", field="threadId")
    if not _is_list_of_str(to) or not _is_list_of_str(cc) or not _is_list_of_str(bcc):
        _log("error", gmail_account_id, "VALIDATION_ERROR", "to/cc/bcc must be arrays of strings when provided.")
        return _err("VALIDATION_ERROR", "to/cc/bcc must be arrays of strings when provided.")
    if subject is not None and not isinstance(subject, str):
        _log("error", gmail_account_id, "VALIDATION_ERROR", "subject must be a string when provided.")
        return _err("VALIDATION_ERROR", "subject must be a string when provided.", field="subject")
    if body is not None and not isinstance(body, str):
        _log("error", gmail_account_id, "VALIDATION_ERROR", "body must be a string when provided.")
        return _err("VALIDATION_ERROR", "body must be a string when provided.", field="body")
    if includeBodyHtml is not None and not isinstance(includeBodyHtml, bool):
        _log("error", gmail_account_id, "VALIDATION_ERROR", "includeBodyHtml must be a boolean when provided.")
        return _err("VALIDATION_ERROR", "includeBodyHtml must be a boolean when provided.", field="includeBodyHtml")

    # If raw provided: accept relaxed base64url check (don't hard-fail on arbitrary strings from callers)
    # The audit showed callers pass non-base64 values; service should accept request and persist.
    if raw is not None and not _looks_like_base64url(raw.strip()):
        _log("error", gmail_account_id, "VALIDATION_ERROR", "raw must be base64url characters when provided.")
        return _err("VALIDATION_ERROR", "raw must be base64url characters when provided.", field="raw")

    # If raw not provided, enforce business rule: must have some content.
    if raw is None:
        if subject is None and body is None and not (to or cc or bcc):
            _log("error", gmail_account_id, "VALIDATION_ERROR", "When raw is not provided, at least one of subject/body/to/cc/bcc must be provided.")
            return _err("VALIDATION_ERROR", "When raw is not provided, at least one of subject/body/to/cc/bcc must be provided.")

    threads = _load("gmail_threads.json")
    if not isinstance(threads, list):
        threads = []

    # threadId is provider thread id; do NOT require it to already exist locally.
    # If it matches an existing local thread for this mailbox, we may link it, else store gmail_thread_id only.
    thread_ref_id = None
    if threadId:
        for th in threads:
            if not isinstance(th, dict):
                continue
            if th.get("gmail_account_id") != gmail_account_id:
                continue
            if th.get("gmail_thread_id") == threadId or th.get("id") == threadId:
                thread_ref_id = th.get("id")
                break

    msgs = _load("gmail_messages.json")
    if not isinstance(msgs, list):
        msgs = []

    # id generation: gmm_<ULID-ish time component>_<seq>
    existing_ids = set()
    for m in msgs:
        if isinstance(m, dict) and isinstance(m.get("id"), str):
            existing_ids.add(m["id"])
    base = int(time.time() * 1000)
    seq = 1
    new_id = f"gmm_{base}_{seq}"
    while new_id in existing_ids:
        seq += 1
        new_id = f"gmm_{base}_{seq}"

    # draft id generation (provider draft id placeholder): gdr_<time>_<seq>
    existing_draft = set()
    for m in msgs:
        if isinstance(m, dict) and isinstance(m.get("gmail_draft_id"), str):
            existing_draft.add(m["gmail_draft_id"])
    dseq = 1
    gmail_draft_id = f"gdr_{base}_{dseq}"
    while gmail_draft_id in existing_draft:
        dseq += 1
        gmail_draft_id = f"gdr_{base}_{dseq}"

    # Compose minimal raw if not provided (best-effort; stored as plain string, not necessarily real base64url)
    raw_store = raw.strip() if isinstance(raw, str) and raw is not None else None
    parsed_from = acct.get("email_address")
    to_list = to if isinstance(to, list) else None
    cc_list = cc if isinstance(cc, list) else None
    bcc_list = bcc if isinstance(bcc, list) else None
    subj = subject if isinstance(subject, str) else None
    body_plain = body if isinstance(body, str) else None

    if raw_store is None:
        hdrs = []
        if parsed_from:
            hdrs.append(f"From: {parsed_from}")
        if to_list:
            hdrs.append("To: " + ", ".join([x for x in to_list if isinstance(x, str)]))
        if cc_list:
            hdrs.append("Cc: " + ", ".join([x for x in cc_list if isinstance(x, str)]))
        if subj is not None:
            hdrs.append(f"Subject: {subj}")
        hdrs.append("MIME-Version: 1.0")
        hdrs.append("Content-Type: text/plain; charset=utf-8")
        composed = "\r\n".join(hdrs) + "\r\n\r\n" + (body_plain or "")
        # Store composed as "raw" even if not base64url; real backend would store provider raw; we persist our composed.
        raw_store = composed

    # Persist draft row
    row = {
        "id": new_id,
        "gmail_account_id": gmail_account_id,
        "gmail_message_id": None,
        "gmail_draft_id": gmail_draft_id,
        "thread_id": thread_ref_id,
        "gmail_thread_id": threadId if threadId else None,
        "is_draft": True,
        "from_address": parsed_from,
        "to": None if raw is not None else to_list,
        "cc": None if raw is not None else cc_list,
        "bcc": None if raw is not None else bcc_list,
        "subject": None if raw is not None else subj,
        "snippet": (body_plain[:120] if isinstance(body_plain, str) else None),
        "body_plain": None if raw is not None else body_plain,
        "body_html": None,
        "raw_rfc2822_base64url": raw_store,
        "internal_date_ms": str(int(time.time() * 1000)),
        "size_estimate_bytes": (len(raw_store.encode("utf-8")) if isinstance(raw_store, str) else None),
        "has_attachment": False,
        "label_ids": [],
        "status": "draft",
        "created_at": now,
        "updated_at": now,
    }

    msgs.append(row)
    _save("gmail_messages.json", msgs)

    # Response: mimic Gmail Draft resource-ish
    out_msg = dict(row)
    if not includeBodyHtml:
        out_msg["body_html"] = None
    _log("success", gmail_account_id, None, None)
    return {"draft": {"id": row["id"], "message": out_msg}}

def delete_draft(id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0088000" if __import__("os").path.isdir("./environment_mix/0088000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, gmail_account_id=None, error_code=None, error_message=None):
        logs = _load("gmail_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"grl_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "delete_draft",
            "gmail_account_id": gmail_account_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("gmail_request_logs.json", logs)

    if not isinstance(id, str) or not id.strip():
        _log("error", None, "VALIDATION_ERROR", "id must be a non-empty string.")
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")
    any_id = id.strip()

    accts = _load("gmail_accounts.json")
    msgs = _load("gmail_messages.json")
    if not isinstance(accts, list):
        accts = []
    if not isinstance(msgs, list):
        msgs = []

    # Find a draft across any connected account (ambient auth) by local id or gmail_draft_id.
    target_idx = None
    target_msg = None
    target_acct = None
    for a in accts:
        if not isinstance(a, dict):
            continue
        if a.get("status") == "disconnected":
            continue
        aid = a.get("id")
        if not aid:
            continue
        for i, m in enumerate(msgs):
            if not isinstance(m, dict):
                continue
            if m.get("gmail_account_id") != aid:
                continue
            if m.get("is_draft") is True and m.get("status") == "draft":
                if m.get("id") == any_id or m.get("gmail_draft_id") == any_id:
                    target_idx = i
                    target_msg = m
                    target_acct = a
                    break
        if target_msg:
            break

    if not target_msg:
        # If there is no connected account at all, this is an auth failure; otherwise it's a not found.
        connected_exists = any(isinstance(a, dict) and a.get("id") and a.get("status") != "disconnected" for a in accts)
        if not connected_exists:
            _log("error", None, "UNAUTHORIZED", "No connected Gmail account context available.")
            return _err("UNAUTHORIZED", "No connected Gmail account context available.")
        _log("error", None, "NOT_FOUND", "Draft not found.")
        return _err("NOT_FOUND", "Draft not found.", id=any_id)

    # Business rule: delete_draft allowed only for is_draft=true and status='draft' (already ensured).
    # Transition: draft -> deleted; clear gmail_draft_id to prevent reuse.
    target_msg["status"] = "deleted"
    target_msg["is_draft"] = True  # keep flag for audit consistency
    target_msg["gmail_draft_id"] = None
    target_msg["updated_at"] = now
    msgs[target_idx] = target_msg
    _save("gmail_messages.json", msgs)

    _log("success", target_acct.get("id"))
    # Gmail style: empty body on success; include minimal envelope with id for usefulness.
    return {"id": any_id, "deleted": True, "status": "deleted"}

def get_draft(id, includeBodyHtml=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0088000" if __import__("os").path.isdir("./environment_mix/0088000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, gmail_account_id=None, error_code=None, error_message=None):
        logs = _load("gmail_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"grl_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "get_draft",
            "gmail_account_id": gmail_account_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        })
        _save("gmail_request_logs.json", logs)

    if not isinstance(id, str) or not id.strip():
        _log("error", None, "VALIDATION_ERROR", "id must be a non-empty string.")
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")
    any_id = id.strip()

    if includeBodyHtml is not None and not isinstance(includeBodyHtml, bool):
        _log("error", None, "VALIDATION_ERROR", "includeBodyHtml must be a boolean.")
        return _err("VALIDATION_ERROR", "includeBodyHtml must be a boolean.", field="includeBodyHtml")
    include_html = bool(includeBodyHtml) if includeBodyHtml is not None else False

    accts = _load("gmail_accounts.json")
    msgs = _load("gmail_messages.json")
    if not isinstance(accts, list):
        accts = []
    if not isinstance(msgs, list):
        msgs = []

    # Find draft only (is_draft=true and status='draft') across any connected account.
    found = None
    found_acct = None
    for a in accts:
        if not isinstance(a, dict):
            continue
        if a.get("status") == "disconnected":
            continue
        aid = a.get("id")
        if not aid:
            continue
        for m in msgs:
            if not isinstance(m, dict):
                continue
            if m.get("gmail_account_id") != aid:
                continue
            if m.get("is_draft") is True and m.get("status") == "draft":
                if m.get("id") == any_id or m.get("gmail_draft_id") == any_id:
                    found = m
                    found_acct = a
                    break
        if found:
            break

    if not found:
        connected_exists = any(isinstance(a, dict) and a.get("id") and a.get("status") != "disconnected" for a in accts)
        if not connected_exists:
            _log("error", None, "UNAUTHORIZED", "No connected Gmail account context available.")
            return _err("UNAUTHORIZED", "No connected Gmail account context available.")
        _log("error", None, "NOT_FOUND", "Draft not found.")
        return _err("NOT_FOUND", "Draft not found.", id=any_id)

    # Return a draft resource; hide body_html unless requested.
    draft = dict(found)
    if not include_html:
        draft.pop("body_html", None)

    _log("success", found_acct.get("id"))
    return {"draft": draft}

def list_drafts(maxResults=None, q=None, includeSpamTrash=None, includeBodyHtml=None, **_extra):
    import json, os, datetime, time, uuid, base64, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0088000" if __import__("os").path.isdir("./environment_mix/0088000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, gmail_account_id=None, error_code=None, error_message=None):
        try:
            logs = _load("gmail_request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "grl_" + uuid.uuid4().hex,
                "endpoint": "list_drafts",
                "gmail_account_id": gmail_account_id,
                "status": status,
                "error_code": error_code,
                "error_message": error_message,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _now(),
            })
            _save("gmail_request_logs.json", logs)
        except Exception:
            pass

    def _resolve_account():
        accts = _load("gmail_accounts.json")
        if not isinstance(accts, list) or not accts:
            return None
        for a in accts:
            if isinstance(a, dict) and a.get("status") == "active":
                return a
        for a in accts:
            if isinstance(a, dict) and a.get("status") in ("active", "suspended"):
                return a
        for a in accts:
            if isinstance(a, dict):
                return a
        return None

    def _encode_token(payload_dict):
        raw = json.dumps(payload_dict, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    acct = _resolve_account()
    if not acct or acct.get("status") != "active":
        _log("error", gmail_account_id=(acct.get("id") if isinstance(acct, dict) else None), error_code="UNAUTHORIZED", error_message="No active connected Gmail account available.")
        return _err("UNAUTHORIZED", "No active connected Gmail account available.")
    gmail_account_id = acct.get("id")

    # Validation
    if maxResults is None:
        max_results = 50
    else:
        if not isinstance(maxResults, (int, float)) or isinstance(maxResults, bool):
            _log("error", gmail_account_id=gmail_account_id, error_code="VALIDATION_ERROR", error_message="maxResults must be a number.")
            return _err("VALIDATION_ERROR", "maxResults must be a number.")
        if int(maxResults) != maxResults:
            # allow floats like 10.0? treat as invalid to be strict
            if not (isinstance(maxResults, float) and maxResults.is_integer()):
                _log("error", gmail_account_id=gmail_account_id, error_code="VALIDATION_ERROR", error_message="maxResults must be an integer between 1 and 500.")
                return _err("VALIDATION_ERROR", "maxResults must be an integer between 1 and 500.")
        max_results = int(maxResults)
        if max_results < 1 or max_results > 500:
            _log("error", gmail_account_id=gmail_account_id, error_code="VALIDATION_ERROR", error_message="maxResults must be between 1 and 500.")
            return _err("VALIDATION_ERROR", "maxResults must be between 1 and 500.")
    if q is not None and not isinstance(q, str):
        _log("error", gmail_account_id=gmail_account_id, error_code="VALIDATION_ERROR", error_message="q must be a string.")
        return _err("VALIDATION_ERROR", "q must be a string.")
    if includeSpamTrash is not None and not isinstance(includeSpamTrash, bool):
        _log("error", gmail_account_id=gmail_account_id, error_code="VALIDATION_ERROR", error_message="includeSpamTrash must be a boolean.")
        return _err("VALIDATION_ERROR", "includeSpamTrash must be a boolean.")
    if includeBodyHtml is not None and not isinstance(includeBodyHtml, bool):
        _log("error", gmail_account_id=gmail_account_id, error_code="VALIDATION_ERROR", error_message="includeBodyHtml must be a boolean.")
        return _err("VALIDATION_ERROR", "includeBodyHtml must be a boolean.")

    include_spam_trash = bool(includeSpamTrash) if includeSpamTrash is not None else False

    messages = _load("gmail_messages.json")
    if not isinstance(messages, list):
        messages = []

    # Filter drafts only: is_draft=true AND status='draft'
    drafts = []
    for m in messages:
        if not isinstance(m, dict):
            continue
        if m.get("gmail_account_id") != gmail_account_id:
            continue
        if not (m.get("is_draft") is True and m.get("status") == "draft"):
            continue
        # includeSpamTrash filter
        if not include_spam_trash:
            lids = m.get("label_ids") or []
            if isinstance(lids, list) and (("SPAM" in lids) or ("TRASH" in lids)):
                continue
        # q: best-effort substring match over subject/snippet/body_plain/to/cc/bcc
        if q:
            hay = []
            for k in ("subject", "snippet", "body_plain"):
                v = m.get(k)
                if isinstance(v, str) and v:
                    hay.append(v)
            for k in ("to", "cc", "bcc"):
                v = m.get(k)
                if isinstance(v, list):
                    hay.extend([s for s in v if isinstance(s, str)])
            blob = "\n".join(hay).lower()
            if q.lower() not in blob:
                continue
        drafts.append(m)

    # Sort: newest first by internal_date_ms if available else created_at
    def _key(m):
        v = m.get("internal_date_ms")
        if isinstance(v, str) and v.isdigit():
            return int(v)
        # created_at iso
        ca = m.get("created_at")
        if isinstance(ca, str):
            try:
                # parse Z
                s = ca.replace("Z", "+00:00")
                return int(datetime.datetime.fromisoformat(s).timestamp() * 1000)
            except Exception:
                return 0
        return 0

    drafts.sort(key=_key, reverse=True)

    total = len(drafts)
    page = drafts[:max_results]
    has_more = total > len(page)
    next_token = None
    if has_more:
        # Token must encode gmail_account_id and query constraints
        token_payload = {
            "v": 1,
            "gmail_account_id": gmail_account_id,
            "q": q or "",
            "includeSpamTrash": include_spam_trash,
            "offset": len(page),
            "ts": _now(),
        }
        next_token = _encode_token(token_payload)

    out_items = []
    for m in page:
        d = dict(m)
        if not includeBodyHtml:
            d.pop("body_html", None)
        out_items.append(d)

    _log("ok", gmail_account_id=gmail_account_id)
    return {
        "drafts": out_items,
        "resultSizeEstimate": total,
        "nextPageToken": next_token,
    }

def send_draft(id, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0088000" if __import__("os").path.isdir("./environment_mix/0088000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix, existing_ids):
        # Deterministic-ish unique id with timestamp + hash; avoids random module.
        base = f"{prefix}_{int(time.time()*1000)}"
        h = hashlib.sha256((base + "|" + str(len(existing_ids))).encode("utf-8")).hexdigest()[:10]
        cand = f"{base}_{h}"
        i = 0
        while cand in existing_ids:
            i += 1
            cand = f"{base}_{h}_{i}"
        return cand

    def _log(status, latency_ms, gmail_account_id=None, meta=None):
        row = {
            "id": _gen_id("req", {r.get("id") for r in reqlog}),
            "endpoint": "send_draft",
            "gmail_account_id": gmail_account_id,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": _now(),
            "meta": meta or {},
        }
        reqlog.append(row)
        _save("request_log.json", reqlog)

    start = time.time()
    reqlog = _load("request_log.json")

    # Basic validation
    if not isinstance(id, str) or not id.strip():
        latency = int((time.time() - start) * 1000)
        _log("VALIDATION_ERROR", latency, None, {"field": "id"})
        return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")

    # Ambient auth: choose an active connected account that can serve request.
    accounts = _load("gmail_accounts.json")
    active_accounts = [a for a in accounts if a.get("status") == "active"]
    if not active_accounts:
        latency = int((time.time() - start) * 1000)
        _log("UNAUTHORIZED", latency, None)
        return _err("UNAUTHORIZED", "No active connected Gmail account available")

    messages = _load("gmail_messages.json")
    threads = _load("gmail_threads.json")

    # Find draft within any active account; but enforce "exactly one mailbox context"
    # by selecting the unique mailbox where this id exists (if multiple, conflict).
    candidates = [m for m in messages if m.get("id") == id and m.get("gmail_account_id") in {a.get("id") for a in active_accounts}]
    if not candidates:
        latency = int((time.time() - start) * 1000)
        _log("NOT_FOUND", latency, None, {"id": id})
        return _err("NOT_FOUND", "Draft not found", id=id)

    if len(candidates) > 1:
        latency = int((time.time() - start) * 1000)
        _log("CONFLICT", latency, None, {"id": id})
        return _err("CONFLICT", "Draft ID is not unique across accessible accounts", id=id)

    draft = candidates[0]
    gmail_account_id = draft.get("gmail_account_id")

    # Ensure mailbox is active (already ensured) and draft is sendable
    if draft.get("is_draft") is not True:
        latency = int((time.time() - start) * 1000)
        _log("CONFLICT", latency, gmail_account_id, {"id": id})
        return _err("CONFLICT", "Message is not a draft", id=id)

    if draft.get("status") != "draft":
        latency = int((time.time() - start) * 1000)
        _log("CONFLICT", latency, gmail_account_id, {"id": id, "status": draft.get("status")})
        return _err("CONFLICT", "Draft is not in a sendable state", id=id, status=draft.get("status"))

    if not draft.get("gmail_draft_id"):
        latency = int((time.time() - start) * 1000)
        _log("CONFLICT", latency, gmail_account_id, {"id": id})
        return _err("CONFLICT", "Draft cannot be sent because it lacks a provider draft id", id=id)

    # Transition: draft -> sent, is_draft false; keep gmail_draft_id for audit
    now = _now()
    draft["status"] = "sent"
    draft["is_draft"] = False
    # Provider would set gmail_message_id/internalDate; we only update what we can without fabrication.
    draft["updated_at"] = now

    # If gmail_thread_id provided, ensure thread record exists for mailbox, else leave as is.
    gth = draft.get("gmail_thread_id")
    if isinstance(gth, str) and gth:
        # link internal thread id if possible
        th = next((t for t in threads if t.get("gmail_account_id") == gmail_account_id and t.get("gmail_thread_id") == gth), None)
        if th:
            draft["thread_id"] = th.get("id")

    # Persist mutation
    # Update in messages list by identity
    updated = 0
    for i, m in enumerate(messages):
        if m.get("id") == id and m.get("gmail_account_id") == gmail_account_id:
            messages[i] = draft
            updated = 1
            break
    if updated != 1:
        latency = int((time.time() - start) * 1000)
        _log("NOT_FOUND", latency, gmail_account_id, {"id": id})
        return _err("NOT_FOUND", "Draft not found for update", id=id)

    _save("gmail_messages.json", messages)

    latency = int((time.time() - start) * 1000)
    _log("OK", latency, gmail_account_id, {"id": id})

    # Return sent message resource (provider-style minimal fields)
    return {
        "message": {
            "id": draft.get("gmail_message_id") or draft.get("id"),
            "threadId": draft.get("gmail_thread_id"),
            "labelIds": draft.get("label_ids") or [],
            "snippet": draft.get("snippet"),
            "internalDate": draft.get("internal_date_ms"),
            "sizeEstimate": draft.get("size_estimate_bytes"),
        },
        "local": draft,
    }

def create_label(name, messageListVisibility=None, labelListVisibility=None, color=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0088000" if __import__("os").path.isdir("./environment_mix/0088000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, gmail_account_id=None, error_code=None, error_message=None):
        logs = _load("gmail_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"grl_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "create_label",
            "gmail_account_id": gmail_account_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        })
        _save("gmail_request_logs.json", logs)

    def _pick_account():
        accts = _load("gmail_accounts.json")
        if not isinstance(accts, list):
            accts = []
        # Prefer active; allow suspended; never disconnected.
        for st in ("active", "suspended"):
            for a in accts:
                if isinstance(a, dict) and a.get("id") and a.get("status") == st:
                    return a
        for a in accts:
            if isinstance(a, dict) and a.get("id") and a.get("status") != "disconnected":
                return a
        return None

    acct = _pick_account()
    if not acct:
        _log("error", None, "UNAUTHORIZED", "No connected Gmail account context available.")
        return _err("UNAUTHORIZED", "No connected Gmail account context available.")
    gmail_account_id = acct["id"]

    if not isinstance(name, str) or not name.strip():
        _log("error", gmail_account_id, "VALIDATION_ERROR", "name is required and must be a non-empty string.")
        return _err("VALIDATION_ERROR", "name is required and must be a non-empty string.", field="name")
    name = name.strip()

    if messageListVisibility is not None and messageListVisibility not in ("show", "hide"):
        _log("error", gmail_account_id, "VALIDATION_ERROR", "messageListVisibility must be one of: show, hide.")
        return _err("VALIDATION_ERROR", "messageListVisibility must be one of: show, hide.", field="messageListVisibility")
    if labelListVisibility is not None and labelListVisibility not in ("labelShow", "labelShowIfUnread", "labelHide"):
        _log("error", gmail_account_id, "VALIDATION_ERROR", "labelListVisibility must be one of: labelShow, labelShowIfUnread, labelHide.")
        return _err("VALIDATION_ERROR", "labelListVisibility must be one of: labelShow, labelShowIfUnread, labelHide.", field="labelListVisibility")

    color_text = None
    color_bg = None
    # Be permissive: if provided but invalid, ignore rather than failing hard (matches real-world behavior tolerance),
    # unless it's explicitly a hex string but malformed.
    if color is not None:
        if not isinstance(color, dict):
            _log("error", gmail_account_id, "VALIDATION_ERROR", "color must be an object.")
            return _err("VALIDATION_ERROR", "color must be an object.", field="color")
        tc = color.get("textColor")
        bc = color.get("backgroundColor")
        # If either is None, treat as not provided.
        hex_re = re.compile(r"^#[0-9A-Fa-f]{6}$")
        if tc is not None:
            if not isinstance(tc, str):
                _log("error", gmail_account_id, "VALIDATION_ERROR", "color.textColor must be a string like #A1B2C3.")
                return _err("VALIDATION_ERROR", "color.textColor must be a string like #A1B2C3.", field="color.textColor")
            if not hex_re.match(tc):
                # tolerate clearly non-hex values by treating as unset instead of rejecting, to accept store-like inputs
                tc = None
            else:
                color_text = tc
        if bc is not None:
            if not isinstance(bc, str):
                _log("error", gmail_account_id, "VALIDATION_ERROR", "color.backgroundColor must be a string like #A1B2C3.")
                return _err("VALIDATION_ERROR", "color.backgroundColor must be a string like #A1B2C3.", field="color.backgroundColor")
            if not hex_re.match(bc):
                bc = None
            else:
                color_bg = bc

    labels = _load("gmail_labels.json")
    if not isinstance(labels, list):
        labels = []

    # Unique(gmail_account_id, name) WHERE status='active'
    for l in labels:
        if not isinstance(l, dict):
            continue
        if l.get("gmail_account_id") == gmail_account_id and l.get("status") == "active" and l.get("name") == name:
            _log("error", gmail_account_id, "CONFLICT", "A label with this name already exists.")
            return _err("CONFLICT", "A label with this name already exists.", field="name", name=name)

    # Generate ids. gmail_label_id is what the Gmail API uses; keep a distinct local id too.
    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%y%m%d%H%M%S')}_{secrets.token_hex(6)}"

    new_row = {
        "id": _new_id("gmlbl"),
        "gmail_account_id": gmail_account_id,
        "gmail_label_id": _new_id("Label"),
        "name": name,
        "label_type": "user",
        "message_list_visibility": messageListVisibility,
        "label_list_visibility": labelListVisibility,
        "color_text": color_text,
        "color_background": color_bg,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }
    labels.append(new_row)
    _save("gmail_labels.json", labels)

    _log("success", gmail_account_id)
    return {"label": new_row}

def delete_label(id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0088000" if __import__("os").path.isdir("./environment_mix/0088000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, gmail_account_id=None, error_code=None, error_message=None):
        logs = _load("gmail_request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"grl_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "delete_label",
            "gmail_account_id": gmail_account_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        })
        _save("gmail_request_logs.json", logs)

    def _resolve_account_for_label(label_any_id):
        accts = _load("gmail_accounts.json")
        labels = _load("gmail_labels.json")
        if not isinstance(accts, list): accts = []
        if not isinstance(labels, list): labels = []
        for a in accts:
            if not isinstance(a, dict): 
                continue
            if a.get("status") == "disconnected":
                continue
            aid = a.get("id")
            if not aid:
                continue
            for l in labels:
                if not isinstance(l, dict): 
                    continue
                if l.get("gmail_account_id") != aid:
                    continue
                if l.get("id") == label_any_id or l.get("gmail_label_id") == label_any_id:
                    return a
        for st in ("active", "suspended"):
            for a in accts:
                if isinstance(a, dict) and a.get("id") and a.get("status") == st:
                    return a
        for a in accts:
            if isinstance(a, dict) and a.get("id") and a.get("status") != "disconnected":
                return a
        return None

    if not isinstance(id, str) or not id.strip():
        acct = _resolve_account_for_label(id if isinstance(id, str) else "")
        _log("error", acct.get("id") if acct else None, "VALIDATION_ERROR", "id must be a non-empty string.")
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")
    id = id.strip()

    acct = _resolve_account_for_label(id)
    if not acct:
        _log("error", None, "UNAUTHORIZED", "No connected Gmail account context available.")
        return _err("UNAUTHORIZED", "No connected Gmail account context available.")
    gmail_account_id = acct["id"]

    labels = _load("gmail_labels.json")
    if not isinstance(labels, list): labels = []

    idx = None
    label = None
    for i, l in enumerate(labels):
        if not isinstance(l, dict):
            continue
        if l.get("gmail_account_id") != gmail_account_id:
            continue
        if l.get("id") == id or l.get("gmail_label_id") == id:
            idx = i
            label = l
            break

    if not label:
        _log("error", gmail_account_id, "NOT_FOUND", "Label not found.")
        return _err("NOT_FOUND", "Label not found.", id=id)

    # Business rule: system labels cannot be deleted
    if label.get("label_type") == "system":
        _log("error", gmail_account_id, "CONFLICT", "System labels cannot be deleted.")
        return _err("CONFLICT", "System labels cannot be deleted.", id=label.get("id"), rule="System labels (label_type='system') cannot be deleted")

    # Lifecycle: active -> deleted only; already deleted is idempotent-ish but must have effect; report NOT_FOUND? Gmail would 404.
    if label.get("status") == "deleted":
        _log("error", gmail_account_id, "NOT_FOUND", "Label not found.")
        return _err("NOT_FOUND", "Label not found.", id=id)

    labels[idx]["status"] = "deleted"
    labels[idx]["updated_at"] = now
    _save("gmail_labels.json", labels)

    _log("success", gmail_account_id, None, None)
    return {"id": label.get("id"), "deleted": True}

def get_label(id, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0088000" if __import__("os").path.isdir("./environment_mix/0088000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix, existing_ids):
        base = f"{prefix}_{int(time.time()*1000)}"
        h = hashlib.sha256((base + "|" + str(len(existing_ids))).encode("utf-8")).hexdigest()[:10]
        cand = f"{base}_{h}"
        i = 0
        while cand in existing_ids:
            i += 1
            cand = f"{base}_{h}_{i}"
        return cand

    def _log(status, latency_ms, gmail_account_id=None, meta=None):
        row = {
            "id": _gen_id("req", {r.get("id") for r in reqlog}),
            "endpoint": "get_label",
            "gmail_account_id": gmail_account_id,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": _now(),
            "meta": meta or {},
        }
        reqlog.append(row)
        _save("request_log.json", reqlog)

    start = time.time()
    reqlog = _load("request_log.json")

    if not isinstance(id, str) or not id.strip():
        latency = int((time.time() - start) * 1000)
        _log("VALIDATION_ERROR", latency, None, {"field": "id"})
        return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")

    accounts = _load("gmail_accounts.json")
    acct = next((a for a in accounts if a.get("status") == "active"), None)
    if not acct:
        latency = int((time.time() - start) * 1000)
        _log("UNAUTHORIZED", latency, None)
        return _err("UNAUTHORIZED", "No active connected Gmail account available")
    gmail_account_id = acct.get("id")

    labels = _load("gmail_labels.json")
    label = next(
        (l for l in labels if l.get("gmail_account_id") == gmail_account_id and (l.get("id") == id or l.get("gmail_label_id") == id) and l.get("status") != "deleted"),
        None,
    )
    if not label:
        latency = int((time.time() - start) * 1000)
        _log("NOT_FOUND", latency, gmail_account_id, {"id": id})
        return _err("NOT_FOUND", "Label not found", id=id)

    latency = int((time.time() - start) * 1000)
    _log("OK", latency, gmail_account_id, {"id": id})

    return {
        "label": {
            "id": label.get("gmail_label_id"),
            "name": label.get("name"),
            "type": label.get("label_type"),
            "messageListVisibility": label.get("message_list_visibility"),
            "labelListVisibility": label.get("label_list_visibility"),
            "color": (None if (label.get("color_text") is None and label.get("color_background") is None) else {"textColor": label.get("color_text"), "backgroundColor": label.get("color_background")}),
        },
