    }

def list_labels(includeDeleted=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0088000" if __import__("os").path.isdir("./environment_mix/0088000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- validation
    if includeDeleted is not None and not isinstance(includeDeleted, bool):
        return _err("VALIDATION_ERROR", "includeDeleted must be a boolean when provided.")

    # --- ambient auth: choose an active connected mailbox that can serve labels/settings calls
    accounts = _load("gmail_accounts.json")
    settings = _load("gmail_settings_entities.json")

    gmail_account = None
    for a in accounts:
        if not isinstance(a, dict):
            continue
        if a.get("status") != "active":
            continue
        # "lacks Gmail settings/labels scope" is modeled by requiring at least one non-deleted settings entity
        # OR existing labels. We'll check settings here and fallback to labels existence below.
        has_settings = any(
            isinstance(s, dict)
            and s.get("gmail_account_id") == a.get("id")
            and s.get("status") in ("active", "pending_verification", "stopped")
            for s in settings
        )
        if has_settings:
            gmail_account = a
            break

    labels = _load("gmail_labels.json")
    if gmail_account is None:
        # fallback: allow if there are labels for an active account (represents connected/scope)
        for a in accounts:
            if not isinstance(a, dict):
                continue
            if a.get("status") != "active":
                continue
            has_labels = any(
                isinstance(l, dict)
                and l.get("gmail_account_id") == a.get("id")
                for l in labels
            )
            if has_labels:
                gmail_account = a
                break

    # request log + rate limiting (per-account, per-endpoint)
    logs = _load("gmail_request_logs.json")
    if not isinstance(logs, list):
        logs = []

    def _log(status, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "list_labels",
            "gmail_account_id": None if gmail_account is None else gmail_account.get("id"),
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": now
        })
        _save("gmail_request_logs.json", logs)

    # If no account can serve the call -> UNAUTHORIZED
    if gmail_account is None:
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No connected Gmail account with sufficient permissions to list labels.")

    # Rate limit: 60 requests / minute for this endpoint per gmail_account_id
    acct_id = gmail_account.get("id")
    one_min_ago = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
    recent = [
        r for r in logs
        if isinstance(r, dict)
        and r.get("gmail_account_id") == acct_id
        and r.get("endpoint") == "list_labels"
        and isinstance(r.get("created_at"), str)
        and r.get("created_at") >= one_min_ago
    ]
    if len(recent) >= 60:
        _log("error", "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Rate limit exceeded for list_labels. Please retry later.")

    # --- read labels within mailbox
    include_deleted = bool(includeDeleted) if includeDeleted is not None else False
    out = []
    for l in labels:
        if not isinstance(l, dict):
            continue
        if l.get("gmail_account_id") != acct_id:
            continue
        if not include_deleted and l.get("status") == "deleted":
            continue
        out.append(l)

    # stable ordering like Gmail: system first then user, then name
    def _sort_key(x):
        lt = x.get("label_type")
        lt_rank = 0 if lt == "system" else 1
        return (lt_rank, (x.get("name") or "").lower(), x.get("gmail_label_id") or "", x.get("id") or "")
    out.sort(key=_sort_key)

    _log("ok", None)
    return {
        "gmail_account": {
            "id": acct_id,
            "email_address": gmail_account.get("email_address")
        },
        "labels": out,
        "resultSizeEstimate": len(out)
    }

def patch_label(id, name=None, messageListVisibility=None, labelListVisibility=None, color=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0088000" if __import__("os").path.isdir("./environment_mix/0088000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
