    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # validation
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id is required and must be a non-empty string.")
    if name is not None and (not isinstance(name, str) or not name.strip()):
        return _err("VALIDATION_ERROR", "name must be a non-empty string when provided.")
    if messageListVisibility is not None:
        if not isinstance(messageListVisibility, str) or messageListVisibility not in ("show", "hide"):
            return _err("VALIDATION_ERROR", "messageListVisibility must be one of: show, hide.")
    if labelListVisibility is not None:
        if not isinstance(labelListVisibility, str) or labelListVisibility not in ("labelShow", "labelShowIfUnread", "labelHide"):
            return _err("VALIDATION_ERROR", "labelListVisibility must be one of: labelShow, labelShowIfUnread, labelHide.")
    if color is not None:
        if not isinstance(color, dict):
            return _err("VALIDATION_ERROR", "color must be an object when provided.")
        if set(color.keys()) != {"textColor", "backgroundColor"}:
            return _err("VALIDATION_ERROR", "color must contain exactly textColor and backgroundColor.")
        tc = color.get("textColor")
        bc = color.get("backgroundColor")
        if not isinstance(tc, str) or not re.fullmatch(r"^#[0-9A-Fa-f]{6}$", tc):
            return _err("VALIDATION_ERROR", "color.textColor must be a hex string like #000000.")
        if not isinstance(bc, str) or not re.fullmatch(r"^#[0-9A-Fa-f]{6}$", bc):
            return _err("VALIDATION_ERROR", "color.backgroundColor must be a hex string like #ffffff.")

    accounts = _load("gmail_accounts.json")
    labels = _load("gmail_labels.json")
    logs = _load("gmail_request_logs.json")
    if not isinstance(logs, list):
        logs = []

    # ambient auth: choose active account that actually owns the label id
    label_row = None
    gmail_account = None
    for l in labels:
        if isinstance(l, dict) and l.get("id") == id:
            label_row = l
            break

    if label_row is not None:
        acct_id = label_row.get("gmail_account_id")
        for a in accounts:
            if isinstance(a, dict) and a.get("id") == acct_id and a.get("status") == "active":
                gmail_account = a
                break

    def _log(status, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "patch_label",
            "gmail_account_id": None if gmail_account is None else gmail_account.get("id"),
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": now
        })
        _save("gmail_request_logs.json", logs)

    if gmail_account is None:
        # If label doesn't exist at all, it's NOT_FOUND; otherwise account inactive -> UNAUTHORIZED
        if label_row is None:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Label not found.")
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Gmail account is not authorized to manage labels.")

    # Ensure label is accessible in this mailbox: status deleted labels are still patchable? Gmail generally forbids.
    # We'll treat deleted as NOT_FOUND to match "not accessible".
    if label_row.get("status") == "deleted":
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Label not found.")

    # system labels cannot be renamed or deleted; for patch: forbid rename; allow visibility/color updates?
    # The tool description suggests "rename or modify a non-editable/system label" -> CONFLICT. We'll prohibit any patch to system.
    if label_row.get("label_type") == "system":
        if any(v is not None for v in (name, messageListVisibility, labelListVisibility, color)):
            _log("error", "CONFLICT")
            return _err("CONFLICT", "System labels are not editable.")

    # uniqueness constraints within mailbox: active name unique (case-sensitive per store). Enforce if renaming.
    acct_id = gmail_account.get("id")
    if name is not None and name != label_row.get("name"):
        for l in labels:
            if not isinstance(l, dict):
                continue
            if l.get("gmail_account_id") != acct_id:
                continue
            if l.get("status") != "active":
                continue
            if l.get("id") == label_row.get("id"):
                continue
            if l.get("name") == name:
                _log("error", "CONFLICT")
                return _err("CONFLICT", "A label with this name already exists.")

    # Apply patch
    changed = False
    if name is not None:
        label_row["name"] = name
        changed = True
    if messageListVisibility is not None:
        label_row["message_list_visibility"] = messageListVisibility
        changed = True
    if labelListVisibility is not None:
        label_row["label_list_visibility"] = labelListVisibility
        changed = True
    if color is not None:
        label_row["color_text"] = color.get("textColor")
        label_row["color_background"] = color.get("backgroundColor")
        changed = True

    if not changed:
        # No-op patch: still return current label (Gmail PATCH is effectively idempotent)
        _log("ok", None)
        return {"label": label_row}

    label_row["updated_at"] = now
    _save("gmail_labels.json", labels)

    _log("ok", None)
    return {"label": label_row}

