def batch_delete_messages(ids, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0088000" if __import__("os").path.isdir("./environment_mix/0088000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, gmail_account_id=None, error_code=None, error_message=None):
        logs = _load("gmail_request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"grl_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "batch_delete_messages",
            "gmail_account_id": gmail_account_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        })
        _save("gmail_request_logs.json", logs)

    def _resolve_account_for_messages(message_ids):
        accts = _load("gmail_accounts.json")
        msgs = _load("gmail_messages.json")
        if not isinstance(accts, list): accts = []
        if not isinstance(msgs, list): msgs = []
        for a in accts:
            if not isinstance(a, dict): 
                continue
            if a.get("status") == "disconnected":
                continue
            aid = a.get("id")
            if not aid:
                continue
            # if any id matches a message for this account, use it
            for mid in message_ids:
                for m in msgs:
                    if isinstance(m, dict) and m.get("gmail_account_id") == aid and (m.get("id") == mid or m.get("gmail_message_id") == mid):
                        return a
        for st in ("active", "suspended"):
            for a in accts:
                if isinstance(a, dict) and a.get("id") and a.get("status") == st:
                    return a
        for a in accts:
            if isinstance(a, dict) and a.get("id") and a.get("status") != "disconnected":
                return a
        return None

    if not isinstance(ids, list) or not ids:
        acct = _resolve_account_for_messages([])
        _log("error", acct.get("id") if acct else None, "VALIDATION_ERROR", "ids must be a non-empty array of strings.")
        return _err("VALIDATION_ERROR", "ids must be a non-empty array of strings.", field="ids")
    for i, mid in enumerate(ids):
        if not isinstance(mid, str) or not mid.strip():
            acct = _resolve_account_for_messages([m for m in ids if isinstance(m, str)])
            _log("error", acct.get("id") if acct else None, "VALIDATION_ERROR", f"ids[{i}] must be a non-empty string.")
            return _err("VALIDATION_ERROR", f"ids[{i}] must be a non-empty string.", field=f"ids[{i}]")
    ids = [m.strip() for m in ids]

    acct = _resolve_account_for_messages(ids)
    if not acct:
        _log("error", None, "UNAUTHORIZED", "No connected Gmail account context available.")
        return _err("UNAUTHORIZED", "No connected Gmail account context available.")
    gmail_account_id = acct["id"]

    msgs = _load("gmail_messages.json")
    if not isinstance(msgs, list): msgs = []

    # Ensure all exist (NOT_FOUND if any missing)
    id_to_index = {}
    for i, m in enumerate(msgs):
        if not isinstance(m, dict):
            continue
        if m.get("gmail_account_id") != gmail_account_id:
            continue
        id_to_index[m.get("id")] = i
        if m.get("gmail_message_id") is not None:
            id_to_index[m.get("gmail_message_id")] = i

    missing = [mid for mid in ids if mid not in id_to_index]
    if missing:
        _log("error", gmail_account_id, "NOT_FOUND", "One or more messages were not found.")
        return _err("NOT_FOUND", "One or more messages were not found.", missing=missing)

    # Transition each to deleted if not already deleted (irreversible). If already deleted, still counts as no effect for that row;
    # but overall must have effect: require at least one actual transition.
    changed = 0
    for mid in ids:
        idx = id_to_index[mid]
        cur = msgs[idx]
        if not isinstance(cur, dict):
            continue
        if cur.get("status") != "deleted":
            msgs[idx]["status"] = "deleted"
            msgs[idx]["updated_at"] = now
            changed += 1

    if changed == 0:
        _log("error", gmail_account_id, "NOT_FOUND", "Messages not found.")
        return _err("NOT_FOUND", "Messages not found.", ids=ids)

    _save("gmail_messages.json", msgs)
    _log("success", gmail_account_id, None, None)
    return {}  # Gmail batchDelete returns empty on success

