            if a.get("status") == "disconnected":
                continue
            aid = a.get("id")
            if not aid:
                continue
            for mid in message_ids:
                for m in msgs:
                    if isinstance(m, dict) and m.get("gmail_account_id") == aid and (m.get("id") == mid or m.get("gmail_message_id") == mid):
                        return a
        for st in ("active", "suspended"):
            for a in accts:
                if isinstance(a, dict) and a.get("id") and a.get("status") == st:
                    return a
        for a in accts:
            if isinstance(a, dict) and a.get("id") and a.get("status") != "disconnected":
                return a
        return None

    if not isinstance(ids, list) or not ids:
        acct = _resolve_account_for_messages([])
        _log("error", acct.get("id") if acct else None, "VALIDATION_ERROR", "`ids` must be a non-empty array of strings.")
        return _err("VALIDATION_ERROR", "`ids` must be a non-empty array of strings.", field="ids")
    for i, mid in enumerate(ids):
        if not isinstance(mid, str) or not mid.strip():
            acct = _resolve_account_for_messages([m for m in ids if isinstance(m, str)])
            _log("error", acct.get("id") if acct else None, "VALIDATION_ERROR", f"ids[{i}] must be a non-empty string.")
            return _err("VALIDATION_ERROR", f"ids[{i}] must be a non-empty string.", field=f"ids[{i}]")
    ids = [m.strip() for m in ids]

    if addLabelIds is None: addLabelIds = []
    if removeLabelIds is None: removeLabelIds = []

    if not isinstance(addLabelIds, list):
        acct = _resolve_account_for_messages(ids)
        _log("error", acct.get("id") if acct else None, "VALIDATION_ERROR", "addLabelIds must be an array of strings.")
        return _err("VALIDATION_ERROR", "addLabelIds must be an array of strings.", field="addLabelIds")
    if not isinstance(removeLabelIds, list):
        acct = _resolve_account_for_messages(ids)
        _log("error", acct.get("id") if acct else None, "VALIDATION_ERROR", "removeLabelIds must be an array of strings.")
        return _err("VALIDATION_ERROR", "removeLabelIds must be an array of strings.", field="removeLabelIds")
    for i, lid in enumerate(addLabelIds):
