            acct = _resolve_account_for_messages(ids)
            _log("error", acct.get("id") if acct else None, "VALIDATION_ERROR", f"addLabelIds[{i}] must be a non-empty string.")
            return _err("VALIDATION_ERROR", f"addLabelIds[{i}] must be a non-empty string.", field=f"addLabelIds[{i}]")
    for i, lid in enumerate(removeLabelIds):
        if not isinstance(lid, str) or not lid.strip():
            acct = _resolve_account_for_messages(ids)
            _log("error", acct.get("id") if acct else None, "VALIDATION_ERROR", f"removeLabelIds[{i}] must be a non-empty string.")
            return _err("VALIDATION_ERROR", f"removeLabelIds[{i}] must be a non-empty string.", field=f"removeLabelIds[{i}]")
    addLabelIds = [s.strip() for s in addLabelIds]
    removeLabelIds = [s.strip() for s in removeLabelIds]

    both = set(addLabelIds).intersection(set(removeLabelIds))
    if both:
        acct = _resolve_account_for_messages(ids)
        _log("error", acct.get("id") if acct else None, "VALIDATION_ERROR", "A label id cannot be both added and removed in the same request.")
        return _err("VALIDATION_ERROR", "A label id cannot be both added and removed in the same request.", conflict_label_ids=sorted(both))

    acct = _resolve_account_for_messages(ids)
    if not acct:
        _log("error", None, "UNAUTHORIZED", "No connected Gmail account context available.")
        return _err("UNAUTHORIZED", "No connected Gmail account context available.")
    gmail_account_id = acct["id"]

    labels = _load("gmail_labels.json")
    if not isinstance(labels, list): labels = []
    allowed_label_ids = set()
    for l in labels:
        if isinstance(l, dict) and l.get("gmail_account_id") == gmail_account_id and l.get("status") == "active":
            if l.get("gmail_label_id"):
                allowed_label_ids.add(l.get("gmail_label_id"))

    for lid in addLabelIds + removeLabelIds:
        if lid not in allowed_label_ids:
            _log("error", gmail_account_id, "NOT_FOUND", "Label not found for this mailbox.")
            return _err("NOT_FOUND", "Label not found for this mailbox.", labelId=lid)

    msgs = _load("gmail_messages.json")
    if not isinstance(msgs, list): msgs = []

    id_to_index = {}
    for i, m in enumerate(msgs):
        if not isinstance(m, dict):
            continue
        if m.get("gmail_account_id") != gmail_account_id:
            continue
        id_to_index[m.get("id")] = i
        if m.get("gmail_message_id") is not None:
            id_to_index[m.get("gmail_message_id")] = i

    missing = [mid for mid in ids if mid not in id_to_index]
    if missing:
        _log("error", gmail_account_id, "NOT_FOUND", "One or more messages were not found.")
        return _err("NOT_FOUND", "One or more messages were not found.", missing=missing)

    changed = 0
    for mid in ids:
        idx = id_to_index[mid]
        m = msgs[idx]
        if not isinstance(m, dict):
            continue
        cur = m.get("label_ids")
        if not isinstance(cur, list):
            cur = []
        cur_set = set([x for x in cur if isinstance(x, str)])
        before = set(cur_set)

        cur_set |= set(addLabelIds)
        cur_set -= set(removeLabelIds)

        if cur_set != before:
            msgs[idx]["label_ids"] = sorted(cur_set)
            msgs[idx]["updated_at"] = now
            changed += 1

    if changed == 0:
        _log("error", gmail_account_id, "NOT_FOUND", "No messages were modified.")
        return _err("NOT_FOUND", "No messages were modified.", ids=ids)

    _save("gmail_messages.json", msgs)
    _log("success", gmail_account_id, None, None)
    return {}

