                    return a
        for a in accts:
            if isinstance(a, dict) and a.get("id"):
                return a
        return None

    if not isinstance(id, str) or not id:
        acct = _resolve_account()
        gmail_account_id = acct.get("id") if acct else None
        _log("error", "VALIDATION_ERROR", "`id` must be a non-empty string.")
        return _err("VALIDATION_ERROR", "`id` must be a non-empty string.")

    if includeBodyHtml is None:
