            target = m
            break

    if not target:
        _log("error", "NOT_FOUND", "Message not found.")
        return _err("NOT_FOUND", "Message not found.")

    # Soft-deleted entities should not be returned by default. For a direct get, Gmail would 404 if deleted.
    if target.get("status") == "deleted":
