def list_messages(maxResults=None, pageToken=None, q=None, labelIds=None, includeSpamTrash=None, includeBodyHtml=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0088000" if __import__("os").path.isdir("./environment_mix/0088000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_messages"
    gmail_account_id = None

    def _log(status, code=None, message=None):
        nonlocal gmail_account_id
        try:
            logs = _load("request_log.json")
            if not isinstance(logs, list):
                logs = []
            row = {
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
                "endpoint": endpoint,
                "gmail_account_id": gmail_account_id,
                "status": status,
                "error_code": code,
                "error_message": message,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": datetime.datetime.utcnow().isoformat() + "Z",
            }
            logs.append(row)
            _save("request_log.json", logs)
        except Exception:
            pass

    def _resolve_account():
        accts = _load("gmail_accounts.json")
        if not isinstance(accts, list) or not accts:
            return None
        for st in ("active", "suspended"):
            for a in accts:
                if isinstance(a, dict) and a.get("status") == st:
                    return a
        for a in accts:
            if isinstance(a, dict) and a.get("id"):
                return a
        return None

    def _now_ms():
        return int(time.time() * 1000)

    def _constraint_sig(acct_id, qv, label_list, inc_spam_trash):
        payload = {
            "gmail_account_id": acct_id,
            "q": qv or "",
            "labelIds": label_list or [],
            "includeSpamTrash": bool(inc_spam_trash),
        }
        blob = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
        return hashlib.sha256(blob).hexdigest()

    def _encode_token(acct_id, qv, label_list, inc_spam_trash, offset):
        tok = {
            "v": 1,
            "gmail_account_id": acct_id,
            "sig": _constraint_sig(acct_id, qv, label_list, inc_spam_trash),
            "q": qv or "",
            "labelIds": label_list or [],
            "includeSpamTrash": bool(inc_spam_trash),
            "offset": int(offset),
            "ts": _now_ms(),
        }
        raw = json.dumps(tok, separators=(",", ":"), sort_keys=True).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_token(token):
        if not isinstance(token, str) or not token:
            return None
        pad = "=" * ((4 - (len(token) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((token + pad).encode("ascii"))
        except Exception:
            return None
        try:
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return None
        if not isinstance(obj, dict):
            return None
        for k in ("v", "gmail_account_id", "sig", "offset"):
            if k not in obj:
                return None
        if obj.get("v") != 1:
            return None
        if not isinstance(obj.get("gmail_account_id"), str) or not isinstance(obj.get("sig"), str):
            return None
        try:
            off = int(obj.get("offset"))
        except Exception:
            return None
        if off < 0:
            return None
        obj["offset"] = off
        if "labelIds" in obj and obj["labelIds"] is not None and not isinstance(obj["labelIds"], list):
            return None
        return obj

    # Defaults / validation
    if maxResults is None:
        maxResults = 50
    # maxResults schema says number; treat as int
    if isinstance(maxResults, bool) or not isinstance(maxResults, (int, float)):
        acct = _resolve_account()
        gmail_account_id = acct.get("id") if acct else None
        _log("error", "VALIDATION_ERROR", "`maxResults` must be a number between 1 and 500.")
        return _err("VALIDATION_ERROR", "`maxResults` must be a number between 1 and 500.")
    maxResults = int(maxResults)
    if maxResults < 1 or maxResults > 500:
        acct = _resolve_account()
        gmail_account_id = acct.get("id") if acct else None
        _log("error", "VALIDATION_ERROR", "`maxResults` must be between 1 and 500.")
        return _err("VALIDATION_ERROR", "`maxResults` must be between 1 and 500.")

    if q is not None and (not isinstance(q, str)):
        acct = _resolve_account()
        gmail_account_id = acct.get("id") if acct else None
        _log("error", "VALIDATION_ERROR", "`q` must be a string when provided.")
        return _err("VALIDATION_ERROR", "`q` must be a string when provided.")

    if labelIds is not None:
        if not isinstance(labelIds, list) or any(not isinstance(x, str) or not x for x in labelIds):
            acct = _resolve_account()
            gmail_account_id = acct.get("id") if acct else None
            _log("error", "VALIDATION_ERROR", "`labelIds` must be an array of strings.")
            return _err("VALIDATION_ERROR", "`labelIds` must be an array of strings.")
    else:
        labelIds = []

    if includeSpamTrash is None:
        includeSpamTrash = False
    if not isinstance(includeSpamTrash, bool):
        acct = _resolve_account()
        gmail_account_id = acct.get("id") if acct else None
        _log("error", "VALIDATION_ERROR", "`includeSpamTrash` must be a boolean when provided.")
        return _err("VALIDATION_ERROR", "`includeSpamTrash` must be a boolean when provided.")

    if includeBodyHtml is None:
        includeBodyHtml = False
    if not isinstance(includeBodyHtml, bool):
        acct = _resolve_account()
        gmail_account_id = acct.get("id") if acct else None
        _log("error", "VALIDATION_ERROR", "`includeBodyHtml` must be a boolean when provided.")
        return _err("VALIDATION_ERROR", "`includeBodyHtml` must be a boolean when provided.")

    acct = _resolve_account()
    if not acct:
        _log("error", "UNAUTHORIZED", "No authenticated Gmail account context is available.")
        return _err("UNAUTHORIZED", "No authenticated Gmail account context is available.")
    gmail_account_id = acct.get("id")

    # Validate pageToken constraints
    offset = 0
    if pageToken is not None:
        tok = _decode_token(pageToken)
        if not tok:
            _log("error", "VALIDATION_ERROR", "Invalid pageToken.")
            return _err("VALIDATION_ERROR", "Invalid pageToken.")
        if tok.get("gmail_account_id") != gmail_account_id:
            _log("error", "VALIDATION_ERROR", "pageToken does not match this mailbox.")
            return _err("VALIDATION_ERROR", "pageToken does not match this mailbox.")
        expected_sig = _constraint_sig(gmail_account_id, q, labelIds, includeSpamTrash)
        if tok.get("sig") != expected_sig:
            _log("error", "VALIDATION_ERROR", "pageToken constraints do not match this request.")
            return _err("VALIDATION_ERROR", "pageToken constraints do not match this request.")
        offset = tok.get("offset", 0)

    # Validate label IDs exist for this mailbox (enforced when supplied as filter)
    if labelIds:
        labels = _load("gmail_labels.json")
        if not isinstance(labels, list):
            labels = []
        existing = set(
            l.get("gmail_label_id")
            for l in labels
            if isinstance(l, dict)
            and l.get("gmail_account_id") == gmail_account_id
            and l.get("status") == "active"
            and isinstance(l.get("gmail_label_id"), str)
        )
        missing = sorted([x for x in labelIds if x not in existing])
        if missing:
            _log("error", "NOT_FOUND", "One or more labelIds do not exist for this mailbox.")
            return _err("NOT_FOUND", "One or more labelIds do not exist for this mailbox.", missing_label_ids=missing)

    msgs = _load("gmail_messages.json")
    if not isinstance(msgs, list):
        msgs = []

    # Filter to mailbox, exclude deleted by default
    rows = []
    qv = (q or "").strip().lower()

    def _labels_of(m):
        ls = m.get("label_ids")
        if not isinstance(ls, list):
            return []
        return [x for x in ls if isinstance(x, str)]

    for m in msgs:
        if not isinstance(m, dict):
            continue
        if m.get("gmail_account_id") != gmail_account_id:
            continue
        if m.get("status") == "deleted":
            continue

        mids_labels = _labels_of(m)

        if not includeSpamTrash:
            if "SPAM" in mids_labels or "TRASH" in mids_labels:
                continue

        # labelIds: intersection semantics (must contain all)
        if labelIds:
            s = set(mids_labels)
            ok = True
            for lid in labelIds:
                if lid not in s:
                    ok = False
                    break
            if not ok:
                continue

        # q: best-effort naive search in subject/from/snippet/body_plain
        if qv:
            hay = " ".join(
                [
                    str(m.get("subject") or ""),
                    str(m.get("from_address") or ""),
                    str(m.get("snippet") or ""),
                    str(m.get("body_plain") or ""),
                ]
            ).lower()
            if qv not in hay:
                continue

        rows.append(m)

    # Sort: Gmail returns newest first; use internal_date_ms desc then created_at desc
    def _k(m):
        v = m.get("internal_date_ms")
        try:
            iv = int(v) if isinstance(v, str) and v.isdigit() else int(v) if isinstance(v, int) else 0
        except Exception:
            iv = 0
        ca = m.get("created_at") or ""
        return (iv, ca)

    rows.sort(key=_k, reverse=True)

    total = len(rows)
    page = rows[offset : offset + maxResults]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_token = _encode_token(gmail_account_id, q, labelIds, includeSpamTrash, next_offset) if has_more else None

    # Shape results: full message resource; optionally drop body_html
    out = []
    for m in page:
        d = dict(m)
        if not includeBodyHtml:
            d.pop("body_html", None)
        out.append(d)

    _log("success")
    return {
        "result": {
            "messages": out,
            "nextPageToken": next_token,
            "resultSizeEstimate": total,
        }
    }

def modify_message(id, addLabelIds=None, removeLabelIds=None, **_extra):
    import json, os, datetime, time, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0088000" if __import__("os").path.isdir("./environment_mix/0088000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "modify_message"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _record(status, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "timestamp": _now(),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    def _check_limits():
        # Best-effort: enforce if a quotas/counters collection exists; otherwise allow.
        now = datetime.datetime.utcnow()
        # Rate limits
        rl_rows = _load("rate_limits.json")
        if isinstance(rl_rows, list) and rl_rows:
            window_s = 60
            limit = None
            for r in rl_rows:
                if isinstance(r, dict) and r.get("scope") in (None, "global") and isinstance(r.get("limit_per_minute"), int):
                    limit = r["limit_per_minute"]
                    window_s = int(r.get("window_seconds") or 60)
                    break
            if isinstance(limit, int) and limit >= 0:
                logs = _load("request_logs.json")
                if not isinstance(logs, list):
                    logs = []
                cutoff = now - datetime.timedelta(seconds=window_s)
                cnt = 0
                for e in logs:
                    if not isinstance(e, dict):
                        continue
                    ts = e.get("timestamp")
                    if not isinstance(ts, str):
                        continue
                    try:
                        dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                    except Exception:
                        continue
                    if dt >= cutoff:
                        cnt += 1
                if cnt >= limit:
                    return _err("RATE_LIMIT", "Rate limit exceeded.")
        # Quotas
        q_rows = _load("quotas.json")
        if isinstance(q_rows, list) and q_rows:
            # Look for a global daily quota
            quota = None
            for r in q_rows:
                if isinstance(r, dict) and r.get("scope") in (None, "global") and isinstance(r.get("daily_limit"), int):
                    quota = r["daily_limit"]
                    break
            if isinstance(quota, int) and quota >= 0:
                logs = _load("request_logs.json")
                if not isinstance(logs, list):
                    logs = []
                start = datetime.datetime(now.year, now.month, now.day)
                cnt = 0
                for e in logs:
                    if not isinstance(e, dict):
                        continue
                    ts = e.get("timestamp")
                    if not isinstance(ts, str):
                        continue
                    try:
                        dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                    except Exception:
                        continue
                    if dt >= start:
                        cnt += 1
                if cnt >= quota:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    def _resolve_account():
        accts = _load("gmail_accounts.json")
        if not isinstance(accts, list) or not accts:
            return None
        # choose an account that can actually serve message operations
        for a in accts:
            if isinstance(a, dict) and a.get("status") == "active":
                return a
        for a in accts:
            if isinstance(a, dict) and a.get("status") in ("suspended", "active"):
                return a
        return None

    def _envelope(msg_row, include_body_html=True):
        # Return as tool would: prefer gmail_message_id for API id; fallback to internal id.
        out = {}
        if not isinstance(msg_row, dict):
            return out
        api_id = msg_row.get("gmail_message_id") or msg_row.get("id")
        out["id"] = api_id
        if msg_row.get("gmail_thread_id") is not None:
            out["threadId"] = msg_row.get("gmail_thread_id")
        if msg_row.get("snippet") is not None:
            out["snippet"] = msg_row.get("snippet")
        if msg_row.get("label_ids") is not None:
            out["labelIds"] = msg_row.get("label_ids")
        if msg_row.get("internal_date_ms") is not None:
            out["internalDate"] = msg_row.get("internal_date_ms")
        if msg_row.get("size_estimate_bytes") is not None:
            out["sizeEstimate"] = msg_row.get("size_estimate_bytes")
        if msg_row.get("raw_rfc2822_base64url") is not None:
            out["raw"] = msg_row.get("raw_rfc2822_base64url")
        # Parsed fields
        if msg_row.get("to") is not None:
            out["to"] = msg_row.get("to")
        if msg_row.get("cc") is not None:
            out["cc"] = msg_row.get("cc")
        if msg_row.get("bcc") is not None:
            out["bcc"] = msg_row.get("bcc")
        if msg_row.get("subject") is not None:
            out["subject"] = msg_row.get("subject")
        if msg_row.get("body_plain") is not None:
            out["body"] = msg_row.get("body_plain")
        if include_body_html and msg_row.get("body_html") is not None:
            out["bodyHtml"] = msg_row.get("body_html")
        out["isDraft"] = bool(msg_row.get("is_draft"))
        out["status"] = msg_row.get("status")
        return out

    # Limits
    lim_err = _check_limits()
    if lim_err:
        _record("error", error_code=lim_err["error"]["code"])
        return lim_err

    # Validate inputs
    if not isinstance(id, str) or not id.strip():
        _record("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`id` must be a non-empty string.")
    if addLabelIds is not None:
        if not isinstance(addLabelIds, list) or any(not isinstance(x, str) for x in addLabelIds):
            _record("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "`addLabelIds` must be an array of strings.")
    if removeLabelIds is not None:
        if not isinstance(removeLabelIds, list) or any(not isinstance(x, str) for x in removeLabelIds):
            _record("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "`removeLabelIds` must be an array of strings.")

    add = addLabelIds or []
    rem = removeLabelIds or []
    if set(add).intersection(set(rem)):
        _record("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "The same label ID cannot be present in both addLabelIds and removeLabelIds.")

    acct = _resolve_account()
    if not acct:
        _record("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authorized Gmail account context available.")
    gmail_account_id = acct["id"]

    # Load message
    msgs = _load("gmail_messages.json")
    if not isinstance(msgs, list):
        msgs = []

    # Tool uses Gmail API message id; support also internal id.
    msg_idx = None
    for i, m in enumerate(msgs):
        if not isinstance(m, dict):
            continue
        if m.get("gmail_account_id") != gmail_account_id:
            continue
        if m.get("gmail_message_id") == id or m.get("id") == id:
            msg_idx = i
            break
    if msg_idx is None:
        _record("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Message not found.")

    mrow = msgs[msg_idx]
    if not isinstance(mrow, dict):
        _record("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Message not found.")

    # Validate referenced labels exist for this mailbox
    labels = _load("gmail_labels.json")
    if not isinstance(labels, list):
        labels = []
    existing_label_ids = set()
    for lr in labels:
        if isinstance(lr, dict) and lr.get("gmail_account_id") == gmail_account_id and lr.get("status") == "active":
            gid = lr.get("gmail_label_id")
            if isinstance(gid, str):
                existing_label_ids.add(gid)

    for lid in add + rem:
        if lid not in existing_label_ids:
            _record("error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", f"Label ID not found: {lid}")

    # Apply modification
    cur = mrow.get("label_ids")
    if cur is None:
        cur = []
    if not isinstance(cur, list) or any(not isinstance(x, str) for x in cur):
        cur = [x for x in cur if isinstance(x, str)] if isinstance(cur, list) else []

    new_set = set(cur)
    for lid in add:
        new_set.add(lid)
    for lid in rem:
        new_set.discard(lid)
    new_labels = list(cur)
    # preserve existing order and append added in stable order
    for lid in add:
        if lid not in new_labels and lid in new_set:
            new_labels.append(lid)
    # remove in place
    new_labels = [x for x in new_labels if x in new_set]
    # If no change, still return updated resource but must have effect? This API call can be idempotent.
    # We'll treat it as success even when resulting labels same.
    mrow["label_ids"] = new_labels
    mrow["updated_at"] = _now()
    msgs[msg_idx] = mrow
    _save("gmail_messages.json", msgs)

    _record("ok")
    return {"message": _envelope(mrow, include_body_html=True)}

def send_message(raw=None, threadId=None, to=None, cc=None, bcc=None, subject=None, body=None, includeBodyHtml=None, **_extra):
    import json, os, datetime, time, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0088000" if __import__("os").path.isdir("./environment_mix/0088000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "send_message"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _record(status, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "timestamp": _now(),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    def _check_limits():
        now = datetime.datetime.utcnow()
        rl_rows = _load("rate_limits.json")
        if isinstance(rl_rows, list) and rl_rows:
            window_s = 60
            limit = None
            for r in rl_rows:
                if isinstance(r, dict) and r.get("scope") in (None, "global") and isinstance(r.get("limit_per_minute"), int):
                    limit = r["limit_per_minute"]
                    window_s = int(r.get("window_seconds") or 60)
                    break
            if isinstance(limit, int) and limit >= 0:
                logs = _load("request_logs.json")
                if not isinstance(logs, list):
                    logs = []
                cutoff = now - datetime.timedelta(seconds=window_s)
                cnt = 0
                for e in logs:
                    if not isinstance(e, dict):
                        continue
                    ts = e.get("timestamp")
                    if not isinstance(ts, str):
                        continue
                    try:
                        dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                    except Exception:
                        continue
                    if dt >= cutoff:
                        cnt += 1
                if cnt >= limit:
                    return _err("RATE_LIMIT", "Rate limit exceeded.")
        q_rows = _load("quotas.json")
        if isinstance(q_rows, list) and q_rows:
            quota = None
            for r in q_rows:
                if isinstance(r, dict) and r.get("scope") in (None, "global") and isinstance(r.get("daily_limit"), int):
                    quota = r["daily_limit"]
                    break
            if isinstance(quota, int) and quota >= 0:
                logs = _load("request_logs.json")
                if not isinstance(logs, list):
                    logs = []
                start = datetime.datetime(now.year, now.month, now.day)
                cnt = 0
                for e in logs:
                    if not isinstance(e, dict):
                        continue
                    ts = e.get("timestamp")
                    if not isinstance(ts, str):
                        continue
                    try:
                        dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                    except Exception:
                        continue
                    if dt >= start:
                        cnt += 1
                if cnt >= quota:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    def _resolve_account():
        accts = _load("gmail_accounts.json")
        if not isinstance(accts, list) or not accts:
            return None
        for a in accts:
            if isinstance(a, dict) and a.get("status") == "active":
                return a
        for a in accts:
            if isinstance(a, dict) and a.get("status") in ("suspended", "active"):
                return a
        return None

    def _gen_id(prefix, rows):
        # Find max numeric suffix and increment; fallback to timestamp-based.
        mx = 0
        for r in rows:
            if not isinstance(r, dict):
                continue
            rid = r.get("id")
            if isinstance(rid, str) and rid.startswith(prefix):
                m = re.match(r"^" + re.escape(prefix) + r"(\d+)$", rid)
                if m:
                    try:
                        mx = max(mx, int(m.group(1)))
                    except Exception:
                        pass
        if mx > 0:
            return f"{prefix}{mx+1}"
        return f"{prefix}{int(time.time()*1000)}"

    def _make_base64url(s):
        return base64.urlsafe_b64encode(s.encode("utf-8")).decode("ascii").rstrip("=")

    def _envelope(msg_row, include_body_html=False):
        out = {}
        api_id = msg_row.get("gmail_message_id") or msg_row.get("id")
        out["id"] = api_id
        if msg_row.get("gmail_thread_id") is not None:
            out["threadId"] = msg_row.get("gmail_thread_id")
        if msg_row.get("snippet") is not None:
            out["snippet"] = msg_row.get("snippet")
        if msg_row.get("label_ids") is not None:
            out["labelIds"] = msg_row.get("label_ids")
        if msg_row.get("internal_date_ms") is not None:
            out["internalDate"] = msg_row.get("internal_date_ms")
        if msg_row.get("size_estimate_bytes") is not None:
            out["sizeEstimate"] = msg_row.get("size_estimate_bytes")
        if msg_row.get("raw_rfc2822_base64url") is not None:
            out["raw"] = msg_row.get("raw_rfc2822_base64url")
        if msg_row.get("to") is not None:
            out["to"] = msg_row.get("to")
        if msg_row.get("cc") is not None:
            out["cc"] = msg_row.get("cc")
        if msg_row.get("bcc") is not None:
            out["bcc"] = msg_row.get("bcc")
        if msg_row.get("subject") is not None:
            out["subject"] = msg_row.get("subject")
        if msg_row.get("body_plain") is not None:
            out["body"] = msg_row.get("body_plain")
        if include_body_html and msg_row.get("body_html") is not None:
            out["bodyHtml"] = msg_row.get("body_html")
        out["isDraft"] = bool(msg_row.get("is_draft"))
        out["status"] = msg_row.get("status")
        return out

    lim_err = _check_limits()
    if lim_err:
        _record("error", error_code=lim_err["error"]["code"])
        return lim_err

    acct = _resolve_account()
    if not acct:
        _record("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authorized Gmail account context available.")
    gmail_account_id = acct["id"]

    # Validate
    if raw is not None and (not isinstance(raw, str) or not raw.strip()):
        _record("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`raw` must be a non-empty string when provided.")
    if threadId is not None and (not isinstance(threadId, str) or not threadId.strip()):
        _record("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`threadId` must be a non-empty string when provided.")
    if includeBodyHtml is not None and not isinstance(includeBodyHtml, bool):
        _record("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`includeBodyHtml` must be a boolean when provided.")

    # If raw provided, ignore other composition fields.
    if raw is None:
        if to is not None:
            if not isinstance(to, list) or any(not isinstance(x, str) for x in to):
                _record("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "`to` must be an array of strings when provided.")
        if cc is not None:
            if not isinstance(cc, list) or any(not isinstance(x, str) for x in cc):
                _record("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "`cc` must be an array of strings when provided.")
        if bcc is not None:
            if not isinstance(bcc, list) or any(not isinstance(x, str) for x in bcc):
                _record("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "`bcc` must be an array of strings when provided.")
        if subject is not None and not isinstance(subject, str):
            _record("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "`subject` must be a string when provided.")
        if body is not None and not isinstance(body, str):
            _record("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "`body` must be a string when provided.")
        # Minimal composed fields: must have at least subject or body, and at least one recipient among to/cc/bcc
        recips = []
        for arr in (to or []) + (cc or []) + (bcc or []):
            if isinstance(arr, str) and arr.strip():
                recips.append(arr.strip())
        if not recips:
            _record("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "At least one recipient must be provided in `to`, `cc`, or `bcc` when `raw` is not provided.")
        if (subject is None or not subject.strip()) and (body is None or not body.strip()):
            _record("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Either `subject` or `body` must be provided when `raw` is not provided.")

    # Compose or accept raw
    if raw is None:
        headers = []
        headers.append(f"To: {', '.join([x.strip() for x in (to or []) if isinstance(x, str) and x.strip()])}")
        if cc:
            ccv = ", ".join([x.strip() for x in cc if isinstance(x, str) and x.strip()])
            if ccv:
                headers.append(f"Cc: {ccv}")
        if bcc:
            bccv = ", ".join([x.strip() for x in bcc if isinstance(x, str) and x.strip()])
            if bccv:
                headers.append(f"Bcc: {bccv}")
        if subject is not None:
            headers.append(f"Subject: {subject}")
        headers.append("MIME-Version: 1.0")
        headers.append("Content-Type: text/plain; charset=utf-8")
        msg_text = "\r\n".join(headers) + "\r\n\r\n" + (body or "")
        raw_to_store = _make_base64url(msg_text)
        parsed_to = [x.strip() for x in (to or []) if isinstance(x, str) and x.strip()] or None
        parsed_cc = [x.strip() for x in (cc or []) if isinstance(x, str) and x.strip()] or None
        parsed_bcc = [x.strip() for x in (bcc or []) if isinstance(x, str) and x.strip()] or None
        parsed_subject = subject
        body_plain = body
        body_html = None
    else:
        raw_to_store = raw.strip()
        parsed_to = parsed_cc = parsed_bcc = None
        parsed_subject = None
        body_plain = None
        body_html = None

    # Ensure thread exists if threadId provided? Gmail can associate by gmail_thread_id even if not locally present.
    # We'll allow any string, just persist gmail_thread_id.

    msgs = _load("gmail_messages.json")
    if not isinstance(msgs, list):
        msgs = []

    # Create new message row (simulate provider confirm send immediately)
    now = _now()
    internal_date_ms = str(int(time.time() * 1000))
    new_row = {
        "id": _gen_id("gmsg_", msgs),
        "gmail_account_id": gmail_account_id,
        "gmail_message_id": f"msg_{int(time.time()*1000)}",  # provider id simulation; must be stable & unique within account
        "gmail_draft_id": None,
        "thread_id": None,
        "gmail_thread_id": (threadId.strip() if isinstance(threadId, str) and threadId.strip() else None),
        "is_draft": False,
        "from_address": acct.get("email_address"),
        "to": parsed_to,
        "cc": parsed_cc,
        "bcc": parsed_bcc,
        "subject": parsed_subject,
        "snippet": (body_plain[:120] if isinstance(body_plain, str) and body_plain else None),
        "body_plain": body_plain,
        "body_html": body_html,
        "raw_rfc2822_base64url": raw_to_store,
        "internal_date_ms": internal_date_ms,
        "size_estimate_bytes": (len(raw_to_store) if isinstance(raw_to_store, str) else None),
        "has_attachment": False,
        "label_ids": ["SENT"],
        "status": "sent",
        "created_at": now,
        "updated_at": now,
    }

    # Uniqueness safeguard for gmail_message_id within mailbox
    for r in msgs:
        if isinstance(r, dict) and r.get("gmail_account_id") == gmail_account_id and r.get("gmail_message_id") == new_row["gmail_message_id"]:
            # extremely unlikely; adjust
            new_row["gmail_message_id"] = f"msg_{int(time.time()*1000)}_{len(msgs)+1}"
            break

    msgs.append(new_row)
    _save("gmail_messages.json", msgs)

    _record("ok")
    return {"message": _envelope(new_row, include_body_html=bool(includeBodyHtml))}

