                    window_s = int(r.get("window_seconds") or 60)
                    break
            if isinstance(limit, int) and limit >= 0:
                logs = _load("request_logs.json")
                if not isinstance(logs, list):
                    logs = []
                cutoff = now - datetime.timedelta(seconds=window_s)
                cnt = 0
                for e in logs:
                    if not isinstance(e, dict):
                        continue
                    ts = e.get("timestamp")
                    if not isinstance(ts, str):
                        continue
                    try:
                        dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                    except Exception:
                        continue
                    if dt >= cutoff:
                        cnt += 1
                if cnt >= limit:
                    return _err("RATE_LIMIT", "Rate limit exceeded.")
        q_rows = _load("quotas.json")
        if isinstance(q_rows, list) and q_rows:
            quota = None
            for r in q_rows:
                if isinstance(r, dict) and r.get("scope") in (None, "global") and isinstance(r.get("daily_limit"), int):
                    quota = r["daily_limit"]
                    break
            if isinstance(quota, int) and quota >= 0:
                logs = _load("request_logs.json")
                if not isinstance(logs, list):
                    logs = []
                start = datetime.datetime(now.year, now.month, now.day)
                cnt = 0
                for e in logs:
                    if not isinstance(e, dict):
                        continue
                    ts = e.get("timestamp")
                    if not isinstance(ts, str):
                        continue
                    try:
                        dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                    except Exception:
                        continue
                    if dt >= start:
                        cnt += 1
                if cnt >= quota:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    def _resolve_account():
        accts = _load("gmail_accounts.json")
        if not isinstance(accts, list) or not accts:
            return None
        for a in accts:
            if isinstance(a, dict) and a.get("status") == "active":
                return a
        for a in accts:
            if isinstance(a, dict) and a.get("status") in ("suspended", "active"):
                return a
        return None

    def _envelope(msg_row):
        out = {}
        api_id = msg_row.get("gmail_message_id") or msg_row.get("id")
        out["id"] = api_id
        if msg_row.get("gmail_thread_id") is not None:
            out["threadId"] = msg_row.get("gmail_thread_id")
        if msg_row.get("snippet") is not None:
            out["snippet"] = msg_row.get("snippet")
        if msg_row.get("label_ids") is not None:
            out["labelIds"] = msg_row.get("label_ids")
        out["isDraft"] = bool(msg_row.get("is_draft"))
        out["status"] = msg_row.get("status")
        return out

    lim_err = _check_limits()
    if lim_err:
        _record("error", error_code=lim_err["error"]["code"])
        return lim_err

    if not isinstance(id, str) or not id.strip():
        _record("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`id` must be a non-empty string.")

    acct = _resolve_account()
    if not acct:
        _record("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authorized Gmail account context available.")
    gmail_account_id = acct["id"]

    msgs = _load("gmail_messages.json")
    if not isinstance(msgs, list):
        msgs = []

    msg_idx = None
    for i, m in enumerate(msgs):
        if not isinstance(m, dict):
            continue
        if m.get("gmail_account_id") != gmail_account_id:
            continue
        if m.get("gmail_message_id") == id or m.get("id") == id:
            msg_idx = i
            break
    if msg_idx is None:
        _record("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Message not found.")

    mrow = msgs[msg_idx]
    cur = mrow.get("status")
    if cur not in ("draft", "sent", "received", "trashed", "deleted"):
        _record("error", error_code="INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", f"Message is in an unknown state: {cur}")

    if cur != "trashed":
        if cur == "deleted":
            _record("error", error_code="INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Cannot untrash a deleted message.")
        if cur == "draft":
            _record("error", error_code="INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Cannot untrash a draft message.")
        # idempotent for non-trashed? real Gmail returns message unchanged only when in TRASH; enforce transition rules
        _record("error", error_code="INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Message is not in TRASH.")

    # Restore to previous non-deleted state; if we can't know, default to 'received' unless it has SENT label.
    labels = mrow.get("label_ids")
    if not isinstance(labels, list):
        labels = []
    labels = [x for x in labels if isinstance(x, str)]

    was_sent = "SENT" in labels
    mrow["status"] = "sent" if was_sent else "received"

    # Remove TRASH label; optionally restore INBOX for received
    labels = [x for x in labels if x != "TRASH"]
    if not was_sent and "INBOX" not in labels:
        labels.append("INBOX")
    mrow["label_ids"] = labels
    mrow["updated_at"] = _now()
    msgs[msg_idx] = mrow
    _save("gmail_messages.json", msgs)

    _record("ok")
    return {"message": _envelope(mrow)}

def get_attachment(messageId, id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0088000" if __import__("os").path.isdir("./environment_mix/0088000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, gmail_account_id=None, error_code=None, error_message=None):
        logs = _load("gmail_request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"grl_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "get_attachment",
            "gmail_account_id": gmail_account_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        })
        _save("gmail_request_logs.json", logs)

    def _resolve_account_for_message(mid):
        accts = _load("gmail_accounts.json")
        msgs = _load("gmail_messages.json")
        if not isinstance(accts, list): accts = []
        if not isinstance(msgs, list): msgs = []
        for a in accts:
            if not isinstance(a, dict): 
                continue
            if a.get("status") == "disconnected":
                continue
            aid = a.get("id")
            if not aid:
                continue
            for m in msgs:
                if isinstance(m, dict) and m.get("gmail_account_id") == aid and (m.get("id") == mid or m.get("gmail_message_id") == mid):
                    return a
        for st in ("active", "suspended"):
            for a in accts:
                if isinstance(a, dict) and a.get("id") and a.get("status") == st:
                    return a
        for a in accts:
            if isinstance(a, dict) and a.get("id") and a.get("status") != "disconnected":
                return a
        return None

    if not isinstance(messageId, str) or not messageId.strip():
        acct = _resolve_account_for_message(messageId if isinstance(messageId, str) else "")
        _log("error", acct.get("id") if acct else None, "VALIDATION_ERROR", "messageId must be a non-empty string.")
        return _err("VALIDATION_ERROR", "messageId must be a non-empty string.", field="messageId")
    if not isinstance(id, str) or not id.strip():
        acct = _resolve_account_for_message(messageId.strip() if isinstance(messageId, str) else "")
        _log("error", acct.get("id") if acct else None, "VALIDATION_ERROR", "id must be a non-empty string.")
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")
    messageId = messageId.strip()
    id = id.strip()

    acct = _resolve_account_for_message(messageId)
    if not acct:
        _log("error", None, "UNAUTHORIZED", "No connected Gmail account context available.")
        return _err("UNAUTHORIZED", "No connected Gmail account context available.")
    gmail_account_id = acct["id"]

    msgs = _load("gmail_messages.json")
    if not isinstance(msgs, list): msgs = []

    msg = None
    for m in msgs:
        if not isinstance(m, dict):
            continue
        if m.get("gmail_account_id") != gmail_account_id:
            continue
        if m.get("id") == messageId or (m.get("gmail_message_id") is not None and m.get("gmail_message_id") == messageId):
            msg = m
            break

    if not msg or msg.get("status") == "deleted":
        _log("error", gmail_account_id, "NOT_FOUND", "Message not found.")
        return _err("NOT_FOUND", "Message not found.", messageId=messageId)

    # Attachments may be cached inside message payload. We support common shapes.
    # Prefer explicit cached map: attachments_by_id: { "<attId>": {"data": "...", "mimeType": "...", "filename": "..."} }
    payload = msg.get("payload") if isinstance(msg.get("payload"), dict) else {}
    attachments_by_id = payload.get("attachments_by_id") if isinstance(payload.get("attachments_by_id"), dict) else None
    if attachments_by_id and id in attachments_by_id and isinstance(attachments_by_id[id], dict):
        att = attachments_by_id[id]
        data = att.get("data")
        if data is None:
            _log("error", gmail_account_id, "NOT_FOUND", "Attachment not found.")
            return _err("NOT_FOUND", "Attachment not found.", messageId=messageId, id=id)
        _log("success", gmail_account_id, None, None)
        return {"attachmentId": id, "data": data, "mimeType": att.get("mimeType"), "filename": att.get("filename")}

    # Also support list in payload.parts with {"body":{"attachmentId":...,"data":...}}
    parts = payload.get("parts") if isinstance(payload.get("parts"), list) else []
    found = None
    for p in parts:
        if not isinstance(p, dict):
            continue
        body = p.get("body") if isinstance(p.get("body"), dict) else {}
        if body.get("attachmentId") == id:
            found = {"attachmentId": id, "data": body.get("data"), "mimeType": p.get("mimeType"), "filename": p.get("filename")}
            break
    if found and found.get("data") is not None:
        _log("success", gmail_account_id, None, None)
        return found

    _log("error", gmail_account_id, "NOT_FOUND", "Attachment not found.")
    return _err("NOT_FOUND", "Attachment not found.", messageId=messageId, id=id)

def delete_thread(id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0088000" if __import__("os").path.isdir("./environment_mix/0088000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, gmail_account_id=None, error_code=None, error_message=None):
        logs = _load("gmail_request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"grl_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "delete_thread",
            "gmail_account_id": gmail_account_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        })
        _save("gmail_request_logs.json", logs)

    def _resolve_account_for_thread(thread_any_id):
        accts = _load("gmail_accounts.json")
        threads = _load("gmail_threads.json")
        if not isinstance(accts, list): accts = []
        if not isinstance(threads, list): threads = []
        for a in accts:
            if not isinstance(a, dict): 
                continue
            if a.get("status") == "disconnected":
                continue
            aid = a.get("id")
            if not aid:
                continue
            for t in threads:
                if isinstance(t, dict) and t.get("gmail_account_id") == aid and (t.get("id") == thread_any_id or t.get("gmail_thread_id") == thread_any_id):
                    return a
        for st in ("active", "suspended"):
            for a in accts:
                if isinstance(a, dict) and a.get("id") and a.get("status") == st:
                    return a
        for a in accts:
            if isinstance(a, dict) and a.get("id") and a.get("status") != "disconnected":
                return a
        return None

    if not isinstance(id, str) or not id.strip():
        acct = _resolve_account_for_thread(id if isinstance(id, str) else "")
        _log("error", acct.get("id") if acct else None, "VALIDATION_ERROR", "id must be a non-empty string.")
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")
    id = id.strip()

    acct = _resolve_account_for_thread(id)
    if not acct:
        _log("error", None, "UNAUTHORIZED", "No connected Gmail account context available.")
        return _err("UNAUTHORIZED", "No connected Gmail account context available.")
    gmail_account_id = acct["id"]

    threads = _load("gmail_threads.json")
    if not isinstance(threads, list): threads = []

    idx = None
    th = None
    for i, t in enumerate(threads):
        if not isinstance(t, dict):
            continue
        if t.get("gmail_account_id") != gmail_account_id:
            continue
        if t.get("id") == id or (t.get("gmail_thread_id") is not None and t.get("gmail_thread_id") == id):
            idx = i
            th = t
            break

    if not th or th.get("status") == "deleted":
        _log("error", gmail_account_id, "NOT_FOUND", "Thread not found.")
        return _err("NOT_FOUND", "Thread not found.", id=id)

    threads[idx]["status"] = "deleted"
    threads[idx]["updated_at"] = now
    _save("gmail_threads.json", threads)

    # Also delete messages in that thread for consistency (Gmail delete thread deletes all messages)
    msgs = _load("gmail_messages.json")
    if not isinstance(msgs, list): msgs = []
    changed_msgs = 0
    for i, m in enumerate(msgs):
        if not isinstance(m, dict):
            continue
        if m.get("gmail_account_id") != gmail_account_id:
            continue
        # match by internal thread_id or gmail_thread_id
        if (th.get("id") and m.get("thread_id") == th.get("id")) or (th.get("gmail_thread_id") and m.get("gmail_thread_id") == th.get("gmail_thread_id")):
            if m.get("status") != "deleted":
                msgs[i]["status"] = "deleted"
                msgs[i]["updated_at"] = now
                changed_msgs += 1
    if changed_msgs:
        _save("gmail_messages.json", msgs)

    _log("success", gmail_account_id, None, None)
    return {"thread": threads[idx]}

def get_thread(id, includeBodyHtml=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0088000" if __import__("os").path.isdir("./environment_mix/0088000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, gmail_account_id, status, latency_ms):
        logs = _load("gmail_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
                "endpoint": endpoint,
                "gmail_account_id": gmail_account_id,
                "status": status,
                "latency_ms": int(latency_ms),
                "created_at": _now(),
            }
        )
        _save("gmail_request_logs.json", logs)

    t0 = time.time()

    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id is required and must be a non-empty string")
    if includeBodyHtml is not None and not isinstance(includeBodyHtml, bool):
        return _err("VALIDATION_ERROR", "includeBodyHtml must be a boolean when provided")

    accounts = _load("gmail_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    active_accounts = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active"]
    if not active_accounts:
        _log("get_thread", None, "UNAUTHORIZED", (time.time() - t0) * 1000)
        return _err("UNAUTHORIZED", "No authorized active Gmail account available for this request")
    gmail_account_id = active_accounts[0].get("id")

    threads = _load("gmail_threads.json")
    if not isinstance(threads, list):
        threads = []
    thread = None
    for th in threads:
        if not isinstance(th, dict):
            continue
        if th.get("gmail_account_id") != gmail_account_id:
            continue
        if th.get("gmail_thread_id") == id or th.get("id") == id:
            thread = th
            break

    if not thread or thread.get("status") == "deleted":
        _log("get_thread", gmail_account_id, "NOT_FOUND", (time.time() - t0) * 1000)
        return _err("NOT_FOUND", "Thread not found")

    messages = _load("gmail_messages.json")
    if not isinstance(messages, list):
        messages = []

    thread_messages = []
    for m in messages:
        if not isinstance(m, dict):
            continue
        if m.get("gmail_account_id") != gmail_account_id:
            continue
        if m.get("status") == "deleted":
            continue
        same_thread = False
        if thread.get("id") and m.get("thread_id") == thread.get("id"):
            same_thread = True
        elif thread.get("gmail_thread_id") and m.get("gmail_thread_id") == thread.get("gmail_thread_id"):
            same_thread = True
        if not same_thread:
            continue

        # Return message resource; omit body_html unless includeBodyHtml=true
        mm = dict(m)
        if not includeBodyHtml:
            mm.pop("body_html", None)
        thread_messages.append(mm)

    # Sort by internal_date_ms ascending when present; fallback created_at.
    def _sort_key(m):
        v = m.get("internal_date_ms")
        try:
            return (0, int(v)) if v is not None else (1, m.get("created_at") or "")
        except Exception:
            return (1, m.get("created_at") or "")

    thread_messages.sort(key=_sort_key)

    out = dict(thread)
    out["messages"] = thread_messages
    _log("get_thread", gmail_account_id, "OK", (time.time() - t0) * 1000)
    return {"thread": out}

def list_threads(maxResults=None, pageToken=None, q=None, labelIds=None, includeSpamTrash=None, includeBodyHtml=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0088000" if __import__("os").path.isdir("./environment_mix/0088000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, gmail_account_id, status, latency_ms):
        logs = _load("gmail_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
                "endpoint": endpoint,
                "gmail_account_id": gmail_account_id,
                "status": status,
                "latency_ms": int(latency_ms),
                "created_at": _now(),
            }
        )
        _save("gmail_request_logs.json", logs)

    t0 = time.time()

    # Validate inputs
    if maxResults is not None:
        if not isinstance(maxResults, (int, float)) or isinstance(maxResults, bool):
            return _err("VALIDATION_ERROR", "maxResults must be a number")
        if int(maxResults) != maxResults:
            # allow floats that are integer-ish? we'll require integral
            if not (isinstance(maxResults, float) and maxResults.is_integer()):
                return _err("VALIDATION_ERROR", "maxResults must be an integer between 1 and 500")
        maxResults = int(maxResults)
        if maxResults < 1 or maxResults > 500:
            return _err("VALIDATION_ERROR", "maxResults must be between 1 and 500")
    else:
        maxResults = 50

    if pageToken is not None and (not isinstance(pageToken, str) or not pageToken.strip()):
        return _err("VALIDATION_ERROR", "pageToken must be a non-empty string when provided")
    if q is not None and not isinstance(q, str):
        return _err("VALIDATION_ERROR", "q must be a string when provided")
    if includeSpamTrash is not None and not isinstance(includeSpamTrash, bool):
        return _err("VALIDATION_ERROR", "includeSpamTrash must be a boolean when provided")
    if includeBodyHtml is not None and not isinstance(includeBodyHtml, bool):
        return _err("VALIDATION_ERROR", "includeBodyHtml must be a boolean when provided")
    if labelIds is not None:
        if not isinstance(labelIds, list) or any((not isinstance(x, str) or not x) for x in labelIds):
            return _err("VALIDATION_ERROR", "labelIds must be an array of non-empty strings when provided")

    accounts = _load("gmail_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    active_accounts = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active"]
    if not active_accounts:
        _log("list_threads", None, "UNAUTHORIZED", (time.time() - t0) * 1000)
        return _err("UNAUTHORIZED", "No authorized active Gmail account available for this request")
    gmail_account_id = active_accounts[0].get("id")

    # Validate labelIds exist for this mailbox (business rule for labelIds use)
    if labelIds:
        labels = _load("gmail_labels.json")
        if not isinstance(labels, list):
            labels = []
        existing = {l.get("gmail_label_id") for l in labels if isinstance(l, dict) and l.get("gmail_account_id") == gmail_account_id and l.get("status") == "active"}
        missing = [x for x in labelIds if x not in existing]
        if missing:
            return _err("VALIDATION_ERROR", "One or more labelIds do not exist for this mailbox", missingLabelIds=missing)

    # Decode/validate pageToken
    constraint = {
        "gmail_account_id": gmail_account_id,
        "q": q or "",
        "labelIds": labelIds or [],
        "includeSpamTrash": bool(includeSpamTrash) if includeSpamTrash is not None else False,
    }

    start = 0
    if pageToken is not None:
        try:
            raw = base64.urlsafe_b64decode(pageToken.encode("utf-8") + b"===")
            tok = json.loads(raw.decode("utf-8"))
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid pageToken")
        if not isinstance(tok, dict) or "v" not in tok or "s" not in tok or "c" not in tok:
            return _err("VALIDATION_ERROR", "Invalid pageToken")
        if tok.get("v") != 1:
            return _err("VALIDATION_ERROR", "Invalid pageToken version")
        if not isinstance(tok.get("s"), int) or tok["s"] < 0:
            return _err("VALIDATION_ERROR", "Invalid pageToken cursor")
        tok_c = tok.get("c")
        if not isinstance(tok_c, dict):
            return _err("VALIDATION_ERROR", "Invalid pageToken constraints")
        # Enforce token constraint matching
        for k in ("gmail_account_id", "q", "includeSpamTrash"):
            if tok_c.get(k) != constraint.get(k):
                return _err("VALIDATION_ERROR", "pageToken does not match request constraints")
        if sorted(tok_c.get("labelIds") or []) != sorted(constraint.get("labelIds") or []):
            return _err("VALIDATION_ERROR", "pageToken does not match request constraints")
        start = tok["s"]

    threads = _load("gmail_threads.json")
    if not isinstance(threads, list):
        threads = []
    messages = _load("gmail_messages.json")
    if not isinstance(messages, list):
        messages = []

    # Build thread -> aggregated labelIds from non-deleted messages
    thread_label_map = {}
    thread_latest_ms = {}

    for m in messages:
        if not isinstance(m, dict):
            continue
        if m.get("gmail_account_id") != gmail_account_id:
            continue
        if m.get("status") == "deleted":
            continue
        gt = m.get("gmail_thread_id")
        if not gt:
            continue
        labs = m.get("label_ids") if isinstance(m.get("label_ids"), list) else []
        if gt not in thread_label_map:
            thread_label_map[gt] = set()
        for lab in labs:
            if isinstance(lab, str):
                thread_label_map[gt].add(lab)
        v = m.get("internal_date_ms")
        try:
            iv = int(v) if v is not None else None
        except Exception:
            iv = None
        if iv is not None:
            thread_latest_ms[gt] = max(thread_latest_ms.get(gt, 0), iv)

    # Filter threads
    def _matches_query(th):
        if not q:
            return True
        qq = q.strip().lower()
        # simple offline: match in snippet or gmail_thread_id
        sn = (th.get("snippet") or "").lower()
        gid = (th.get("gmail_thread_id") or "").lower()
        return qq in sn or qq in gid

    def _matches_labels(th):
        if not labelIds:
            return True
        gt = th.get("gmail_thread_id")
        if not gt:
            return False
        labs = thread_label_map.get(gt, set())
        return all(l in labs for l in labelIds)

    def _matches_spam_trash(th):
        if includeSpamTrash:
            return True
        gt = th.get("gmail_thread_id")
        labs = thread_label_map.get(gt, set())
        return ("SPAM" not in labs) and ("TRASH" not in labs)

    candidates = []
    for th in threads:
        if not isinstance(th, dict):
            continue
        if th.get("gmail_account_id") != gmail_account_id:
            continue
        if th.get("status") == "deleted":
            continue
        if not _matches_query(th):
            continue
        if not _matches_labels(th):
            continue
        if not _matches_spam_trash(th):
            continue
        candidates.append(th)

    # Sort by last message internal date desc; fallback updated_at desc
    def _sort_key(th):
        gt = th.get("gmail_thread_id")
        lm = thread_latest_ms.get(gt)
        if lm is not None:
            return (0, -lm)
        # fallback: updated_at string desc
        ua = th.get("updated_at") or ""
        return (1, "".join(chr(255 - ord(c)) for c in ua[:50]))

    candidates.sort(key=_sort_key)

    page = candidates[start : start + maxResults]
    next_token = None
    if start + maxResults < len(candidates):
        tok = {"v": 1, "s": start + maxResults, "c": constraint}
        enc = base64.urlsafe_b64encode(json.dumps(tok, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")
        next_token = enc

    # Include messages if includeBodyHtml requested (and to align with tool description); otherwise just return threads.
    out_threads = []
    if includeBodyHtml:
        # include messages list in each thread
        msg_by_gt = {}
        for m in messages:
            if not isinstance(m, dict):
                continue
            if m.get("gmail_account_id") != gmail_account_id or m.get("status") == "deleted":
                continue
            gt = m.get("gmail_thread_id")
            if not gt:
                continue
            mm = dict(m)
            # includeBodyHtml=True => keep body_html as stored
            msg_by_gt.setdefault(gt, []).append(mm)

        def _msg_sort(m):
            v = m.get("internal_date_ms")
            try:
                return int(v) if v is not None else 0
            except Exception:
                return 0

        for th in page:
            x = dict(th)
            ms = msg_by_gt.get(th.get("gmail_thread_id"), [])
            ms.sort(key=_msg_sort)
            x["messages"] = ms
            out_threads.append(x)
    else:
        out_threads = [dict(th) for th in page]

    _log("list_threads", gmail_account_id, "OK", (time.time() - t0) * 1000)
    return {
        "threads": out_threads,
        "resultSizeEstimate": len(candidates),
        "nextPageToken": next_token,
    }

def modify_thread(id, addLabelIds=None, removeLabelIds=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0088000" if __import__("os").path.isdir("./environment_mix/0088000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    logs_name = "gmail_request_logs.json"

    def _log(endpoint, account_id, status_code, error_code=None, meta=None):
        logs = _load(logs_name)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "gmail_account_id": account_id,
            "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status_code,
        }
        if error_code:
            row["error_code"] = error_code
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save(logs_name, logs)

    def _resolve_account():
        accts = _load("gmail_accounts.json")
        if not isinstance(accts, list):
            return None
        # choose any active account as ambient auth context
        for a in accts:
            if isinstance(a, dict) and a.get("status") == "active":
                return a
        for a in accts:
            if isinstance(a, dict) and a.get("status") in ("suspended", "active"):
                return a
        return None

    def _validate_label_ids(x):
        if x is None:
            return []
        if not isinstance(x, list):
            return None
        for v in x:
            if not isinstance(v, str) or not v.strip():
                return None
        return x

    try:
        if not isinstance(id, str) or not id.strip():
            account = _resolve_account()
            _log("modify_thread", account["id"] if account else None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "id is required and must be a non-empty string")

        add_ids = _validate_label_ids(addLabelIds)
        rem_ids = _validate_label_ids(removeLabelIds)
        if add_ids is None or rem_ids is None:
            account = _resolve_account()
            _log("modify_thread", account["id"] if account else None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "addLabelIds/removeLabelIds must be arrays of non-empty strings")

        add_set = set(add_ids or [])
        rem_set = set(rem_ids or [])
        if add_set & rem_set:
            account = _resolve_account()
            _log("modify_thread", account["id"] if account else None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "A label ID cannot be in both addLabelIds and removeLabelIds")

        account = _resolve_account()
        if not account:
            _log("modify_thread", None, 401, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No authorized Gmail account context available")
        gmail_account_id = account["id"]

        # validate referenced label ids exist for this mailbox
        if add_set or rem_set:
            labels = _load("gmail_labels.json")
            if not isinstance(labels, list):
                labels = []
            existing = set()
            for lr in labels:
                if isinstance(lr, dict) and lr.get("gmail_account_id") == gmail_account_id and lr.get("status") == "active":
                    glid = lr.get("gmail_label_id")
                    if isinstance(glid, str):
                        existing.add(glid)
            missing = [x for x in (list(add_set | rem_set)) if x not in existing]
            if missing:
                _log("modify_thread", gmail_account_id, 400, "VALIDATION_ERROR", meta={"missingLabelIds": missing})
                return _err("VALIDATION_ERROR", "One or more label IDs do not exist for this mailbox", missingLabelIds=missing)

        threads = _load("gmail_threads.json")
        if not isinstance(threads, list):
            threads = []

        thread = None
        for tr in threads:
            if isinstance(tr, dict) and tr.get("gmail_account_id") == gmail_account_id and tr.get("gmail_thread_id") == id:
                thread = tr
                break

        if not thread:
            _log("modify_thread", gmail_account_id, 404, "NOT_FOUND")
            return _err("NOT_FOUND", "Thread not found")

        if thread.get("status") == "deleted":
            _log("modify_thread", gmail_account_id, 409, "CONFLICT")
            return _err("CONFLICT", "Cannot modify a deleted thread")

        # apply label modifications to all messages in this thread (provider-like behavior)
        msgs = _load("gmail_messages.json")
        if not isinstance(msgs, list):
            msgs = []

        affected = 0
        now = datetime.datetime.utcnow().isoformat() + "Z"
        for m in msgs:
            if not isinstance(m, dict):
                continue
            if m.get("gmail_account_id") != gmail_account_id:
                continue
            if m.get("gmail_thread_id") != id:
                continue
            if m.get("status") == "deleted":
                continue
            lids = m.get("label_ids")
            if not isinstance(lids, list):
                lids = []
            lidset = set([x for x in lids if isinstance(x, str)])
            lidset |= add_set
            lidset -= rem_set
            new_lids = sorted(lidset)
            if new_lids != lids:
                m["label_ids"] = new_lids
                m["updated_at"] = now
                affected += 1

        if (add_set or rem_set) and affected == 0:
            # no effect on any messages in thread -> treat as conflict-ish
            _log("modify_thread", gmail_account_id, 409, "CONFLICT", meta={"affected_messages": 0})
            return _err("CONFLICT", "No applicable messages in thread to modify labels")

        thread["updated_at"] = now
        _save("gmail_messages.json", msgs)
        _save("gmail_threads.json", threads)

        # return updated thread resource (local representation)
        out = dict(thread)
        _log("modify_thread", gmail_account_id, 200, meta={"affected_messages": affected})
        return {"thread": out}
    except Exception as e:
        account = None
        try:
            account = _resolve_account()
        except Exception:
            account = None
        _log("modify_thread", account["id"] if account else None, 500, "CONFLICT", meta={"exception": str(e)})
        return _err("CONFLICT", "Unexpected error while modifying thread", detail=str(e))

