            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    logs_name = "gmail_request_logs.json"

    def _log(endpoint, account_id, status_code, error_code=None, meta=None):
        logs = _load(logs_name)
        if not isinstance(logs, list):
