        }
        if error_code:
            row["error_code"] = error_code
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save(logs_name, logs)

    def _resolve_account():
        accts = _load("gmail_accounts.json")
        if not isinstance(accts, list):
            return None
        for a in accts:
            if isinstance(a, dict) and a.get("status") == "active":
                return a
        for a in accts:
            if isinstance(a, dict) and a.get("status") in ("suspended", "active"):
                return a
        return None

    try:
        if not isinstance(id, str) or not id.strip():
            account = _resolve_account()
            _log("trash_thread", account["id"] if account else None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "id is required and must be a non-empty string")

        account = _resolve_account()
        if not account:
            _log("trash_thread", None, 401, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No authorized Gmail account context available")
        gmail_account_id = account["id"]

        threads = _load("gmail_threads.json")
        if not isinstance(threads, list):
            threads = []

        thread = None
        for tr in threads:
            if isinstance(tr, dict) and tr.get("gmail_account_id") == gmail_account_id and tr.get("gmail_thread_id") == id:
                thread = tr
                break

        if not thread:
            _log("trash_thread", gmail_account_id, 404, "NOT_FOUND")
            return _err("NOT_FOUND", "Thread not found")

        st = thread.get("status")
        if st == "trashed":
            _log("trash_thread", gmail_account_id, 409, "CONFLICT")
            return _err("CONFLICT", "Thread is already in TRASH")
        if st == "deleted":
            _log("trash_thread", gmail_account_id, 409, "CONFLICT")
            return _err("CONFLICT", "Cannot trash a deleted thread")

        # transition active -> trashed
        if st != "active":
            _log("trash_thread", gmail_account_id, 409, "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", f"Cannot trash thread from state '{st}'")

        now = datetime.datetime.utcnow().isoformat() + "Z"
        thread["status"] = "trashed"
        thread["updated_at"] = now

        # also trash all non-deleted messages in thread that are in allowed states
        msgs = _load("gmail_messages.json")
        if not isinstance(msgs, list):
            msgs = []
        affected = 0
        for m in msgs:
            if not isinstance(m, dict):
                continue
            if m.get("gmail_account_id") != gmail_account_id:
                continue
            if m.get("gmail_thread_id") != id:
                continue
            mst = m.get("status")
            if mst in ("sent", "received"):
                m["status"] = "trashed"
                m["updated_at"] = now
                affected += 1
            elif mst == "trashed":
                continue
            elif mst == "deleted":
                continue
            # drafts are not part of thread trashing semantics; leave unchanged

        _save("gmail_messages.json", msgs)
        _save("gmail_threads.json", threads)

        out = dict(thread)
        _log("trash_thread", gmail_account_id, 200, meta={"affected_messages": affected})
        return {"thread": out}
    except Exception as e:
        account = None
        try:
            account = _resolve_account()
        except Exception:
            account = None
        _log("trash_thread", account["id"] if account else None, 500, "CONFLICT", meta={"exception": str(e)})
        return _err("CONFLICT", "Unexpected error while trashing thread", detail=str(e))

