        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_auto_forwarding"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, code=None, message=None, gmail_account_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "ts": _now(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "gmail_account_id": gmail_account_id,
        }
        if code:
            row["error_code"] = code
        if message:
            row["error_message"] = message
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(enabled, bool):
        _log("error", "VALIDATION_ERROR", "enabled must be boolean")
        return _err("VALIDATION_ERROR", "enabled must be boolean", field="enabled")
    if not isinstance(emailAddress, str) or not emailAddress.strip():
        _log("error", "VALIDATION_ERROR", "emailAddress must be a non-empty string")
        return _err("VALIDATION_ERROR", "emailAddress must be a non-empty string", field="emailAddress")
    if not isinstance(disposition, str) or disposition not in ("leaveInInbox", "archive", "trash", "markRead"):
        _log("error", "VALIDATION_ERROR", "disposition is invalid")
        return _err("VALIDATION_ERROR", "disposition must be one of leaveInInbox, archive, trash, markRead", field="disposition")

    # Resolve ambient auth: pick a mailbox we can manage settings for
    accounts = _load("gmail_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = None
    for a in accounts:
        if isinstance(a, dict) and a.get("status") == "active":
            acct = a
            break
    if not acct:
        _log("error", "UNAUTHORIZED", "No active gmail account available for this call")
        return _err("UNAUTHORIZED", "Caller is not authorized to manage mailbox settings")

    gmail_account_id = acct.get("id")

    # Business constraint: enabled implies email present (already validated); enforce conflict conditions
    # Provider-like conflict: cannot enable forwarding to same mailbox address.
    if enabled and isinstance(acct.get("email_address"), str) and acct.get("email_address").lower() == emailAddress.strip().lower():
        _log("error", "CONFLICT", "Cannot forward to the same mailbox address", gmail_account_id=gmail_account_id)
        return _err("CONFLICT", "Automatic forwarding to the same mailbox address is not permitted")

    # Mutate account settings
    now = _now()
    updated = False
    for i, a in enumerate(accounts):
        if isinstance(a, dict) and a.get("id") == gmail_account_id:
            # If disconnected/suspended, treat as unauthorized to manage settings
            if a.get("status") != "active":
                _log("error", "UNAUTHORIZED", "Mailbox is not active", gmail_account_id=gmail_account_id)
                return _err("UNAUTHORIZED", "Caller is not authorized to manage mailbox settings")
            a["auto_forwarding_enabled"] = enabled
            a["auto_forwarding_email_address"] = emailAddress.strip()
            a["auto_forwarding_disposition"] = disposition
            a["updated_at"] = now
            accounts[i] = a
            updated = True
            acct = a
            break

    if not updated:
        _log("error", "NOT_FOUND", "Gmail account not found", gmail_account_id=gmail_account_id)
        return _err("NOT_FOUND", "Gmail account not found")

    _save("gmail_accounts.json", accounts)

    resp = {
        "gmailAccountId": gmail_account_id,
        "enabled": acct.get("auto_forwarding_enabled"),
        "emailAddress": acct.get("auto_forwarding_email_address"),
        "disposition": acct.get("auto_forwarding_disposition"),
        "updatedAt": acct.get("updated_at"),
    }
    _log("success", gmail_account_id=gmail_account_id)
    return resp

