    # Validate RFC 3066-ish tag (BCP47). Keep pragmatic: language[-Script][-REGION][-variant...]
    if not isinstance(displayLanguage, str) or not displayLanguage.strip():
        _log("error", "VALIDATION_ERROR", "displayLanguage must be a non-empty string")
