    if not re.fullmatch(r"[A-Za-z]{2,3}(-[A-Za-z]{4})?(-[A-Za-z]{2}|\-\d{3})?(-[A-Za-z0-9]{5,8}|\-[0-9][A-Za-z0-9]{3})*", tag):
        _log("error", "VALIDATION_ERROR", "displayLanguage is not a valid RFC 3066 tag")
        return _err("VALIDATION_ERROR", "displayLanguage must be formatted as an RFC 3066 language tag", field="displayLanguage")

    accounts = _load("gmail_accounts.json")
