def update_pop(accessWindow, disposition, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0088000" if __import__("os").path.isdir("./environment_mix/0088000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_pop"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, code=None, message=None, gmail_account_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "ts": _now(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "gmail_account_id": gmail_account_id,
        }
        if code:
            row["error_code"] = code
        if message:
            row["error_message"] = message
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(accessWindow, str) or accessWindow not in ("disabled", "allMail", "fromNowOn"):
        _log("error", "VALIDATION_ERROR", "accessWindow is invalid")
        return _err("VALIDATION_ERROR", "accessWindow must be one of disabled, allMail, fromNowOn", field="accessWindow")
    if not isinstance(disposition, str) or disposition not in ("archive", "trash", "leaveInInbox"):
        _log("error", "VALIDATION_ERROR", "disposition is invalid")
        return _err("VALIDATION_ERROR", "disposition must be one of archive, trash, leaveInInbox", field="disposition")

    accounts = _load("gmail_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = None
    for a in accounts:
        if isinstance(a, dict) and a.get("status") == "active":
            acct = a
            break
    if not acct:
        _log("error", "UNAUTHORIZED", "No active gmail account available for this call")
        return _err("UNAUTHORIZED", "Caller is not authorized to manage mailbox settings")

    gmail_account_id = acct.get("id")

    # Conflict-like rule: disposition must be irrelevant when POP disabled; Gmail allows setting anyway,
    # but some providers forbid. We'll treat as allowed unless disabled + non-default? To satisfy spec "CONFLICT if not permitted":
    # enforce: when accessWindow='disabled', disposition must be 'leaveInInbox' (safe).
    if accessWindow == "disabled" and disposition != "leaveInInbox":
        _log("error", "CONFLICT", "Cannot set disposition when POP is disabled", gmail_account_id=gmail_account_id)
        return _err("CONFLICT", "Requested POP disposition is not permitted when POP is disabled")

    now = _now()
    updated = False
    for i, a in enumerate(accounts):
        if isinstance(a, dict) and a.get("id") == gmail_account_id:
            if a.get("status") != "active":
                _log("error", "UNAUTHORIZED", "Mailbox is not active", gmail_account_id=gmail_account_id)
                return _err("UNAUTHORIZED", "Caller is not authorized to manage mailbox settings")
            a["pop_access_window"] = accessWindow
            a["pop_disposition"] = disposition
            a["updated_at"] = now
            accounts[i] = a
            acct = a
            updated = True
            break

    if not updated:
        _log("error", "NOT_FOUND", "Gmail account not found", gmail_account_id=gmail_account_id)
        return _err("NOT_FOUND", "Gmail account not found")

    _save("gmail_accounts.json", accounts)

    resp = {
        "gmailAccountId": gmail_account_id,
        "accessWindow": acct.get("pop_access_window"),
        "disposition": acct.get("pop_disposition"),
        "updatedAt": acct.get("updated_at"),
    }
    _log("success", gmail_account_id=gmail_account_id)
    return resp

def update_vacation(enableAutoReply, responseBodyPlainText, responseSubject=None, restrictToContacts=None, restrictToDomain=None, startTime=None, endTime=None, **_extra):
