            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "update_vacation"

    def _log(status, code=None, message=None, gmail_account_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        entry = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "gmail_account_id": gmail_account_id,
            "status": status,
            "error_code": code,
            "error_message": message,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": now
        }
        logs.append(entry)
        try:
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _resolve_account():
        accounts = _load("gmail_accounts.json")
        if not isinstance(accounts, list):
            return None
        # pick any workable account for settings operations: must be active
        for a in accounts:
            if isinstance(a, dict) and a.get("status") == "active":
                return a
        return None

    def _validate_epoch_ms_str(x, field):
        if x is None:
            return None
        if not isinstance(x, str):
            return _err("VALIDATION_ERROR", f"{field} must be a string (epoch ms).", field=field)
        if not re.fullmatch(r"\d{1,20}", x):
            return _err("VALIDATION_ERROR", f"{field} must be an epoch-millisecond string.", field=field)
        # also ensure it fits in int
        try:
            int(x)
        except Exception:
            return _err("VALIDATION_ERROR", f"{field} must be an integer-encoded string.", field=field)
        return None

    # Validate required
    if not isinstance(enableAutoReply, bool):
        _log("error", "VALIDATION_ERROR", "enableAutoReply must be boolean.")
        return _err("VALIDATION_ERROR", "enableAutoReply must be boolean.", field="enableAutoReply")
    if not isinstance(responseBodyPlainText, str) or responseBodyPlainText == "":
        _log("error", "VALIDATION_ERROR", "responseBodyPlainText must be a non-empty string.")
        return _err("VALIDATION_ERROR", "responseBodyPlainText must be a non-empty string.", field="responseBodyPlainText")
    if responseSubject is not None and not isinstance(responseSubject, str):
        _log("error", "VALIDATION_ERROR", "responseSubject must be string.")
        return _err("VALIDATION_ERROR", "responseSubject must be a string.", field="responseSubject")
    if restrictToContacts is not None and not isinstance(restrictToContacts, bool):
        _log("error", "VALIDATION_ERROR", "restrictToContacts must be boolean.")
        return _err("VALIDATION_ERROR", "restrictToContacts must be boolean.", field="restrictToContacts")
    if restrictToDomain is not None and not isinstance(restrictToDomain, bool):
        _log("error", "VALIDATION_ERROR", "restrictToDomain must be boolean.")
        return _err("VALIDATION_ERROR", "restrictToDomain must be boolean.", field="restrictToDomain")

    e = _validate_epoch_ms_str(startTime, "startTime")
    if e:
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    e = _validate_epoch_ms_str(endTime, "endTime")
    if e:
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if startTime is not None and endTime is not None:
        if int(endTime) < int(startTime):
            _log("error", "VALIDATION_ERROR", "endTime must not be earlier than startTime.")
            return _err("VALIDATION_ERROR", "endTime must not be earlier than startTime.", field="endTime")

    acct = _resolve_account()
    if not acct:
        _log("error", "UNAUTHORIZED", "No active mailbox available for settings update.")
        return _err("UNAUTHORIZED", "Not authorized to manage mailbox settings.")

    # Update account row fields for vacation responder
    accounts = _load("gmail_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    updated = None
    for a in accounts:
        if isinstance(a, dict) and a.get("id") == acct.get("id"):
            a["vacation_enable_auto_reply"] = enableAutoReply
            a["vacation_response_subject"] = responseSubject
            a["vacation_response_body_plain_text"] = responseBodyPlainText
            a["vacation_restrict_to_contacts"] = restrictToContacts
            a["vacation_restrict_to_domain"] = restrictToDomain
            a["vacation_start_time_ms"] = startTime
            a["vacation_end_time_ms"] = endTime
            a["updated_at"] = now
            updated = a
            break

    if not updated:
        _log("error", "NOT_FOUND", "Mailbox not found.")
        return _err("NOT_FOUND", "Mailbox not found.")

    # Enforce table-level constraint: end >= start (already), also required fields are present (already)
    _save("gmail_accounts.json", accounts)

    resp = {
        "enableAutoReply": updated.get("vacation_enable_auto_reply"),
        "responseSubject": updated.get("vacation_response_subject"),
        "responseBodyPlainText": updated.get("vacation_response_body_plain_text"),
        "restrictToContacts": updated.get("vacation_restrict_to_contacts"),
        "restrictToDomain": updated.get("vacation_restrict_to_domain"),
        "startTime": updated.get("vacation_start_time_ms"),
        "endTime": updated.get("vacation_end_time_ms")
    }
    _log("ok", gmail_account_id=updated.get("id"))
    return {"vacation": resp}

