                return a
        return None

    if not isinstance(delegateEmail, str) or delegateEmail.strip() == "":
        _log("error", "VALIDATION_ERROR", "delegateEmail is required.")
        return _err("VALIDATION_ERROR", "delegateEmail is required.", field="delegateEmail")
    delegateEmail = delegateEmail.strip()
    # simple syntactic email validation
    if not re.fullmatch(r"[^@\s]+@[^@\s]+\.[^@\s]+", delegateEmail):
        _log("error", "VALIDATION_ERROR", "delegateEmail must be a valid email address.")
        return _err("VALIDATION_ERROR", "delegateEmail must be a valid email address.", field="delegateEmail")

