        "scope_key": None,
        "payload": {
            "delegateEmail": delegateEmail,
            "verificationSentAt": now
        },
        "status": "pending_verification",
        "is_default": None,
        "created_at": now,
        "updated_at": now
    }
    entities.append(row)
    _save("gmail_settings_entities.json", entities)
    _log("ok", gmail_account_id=acct.get("id"))
    return {"delegate": {"delegateEmail": delegateEmail, "verificationStatus": row["status"]}}

