def list_delegates(includeDeleted=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0088000" if __import__("os").path.isdir("./environment_mix/0088000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- auth context resolution (ambient) ----
    accounts = _load("gmail_accounts.json")
    # Choose an account that is active (prefer active, else suspended) for settings reads.
    acct = None
    for st in ("active", "suspended"):
        for a in accounts:
            if isinstance(a, dict) and a.get("status") == st:
                acct = a
                break
        if acct:
            break

    reqlog = _load("request_logs.json")
    if not isinstance(reqlog, list):
        reqlog = []

    def _log(status, code=None, message=None):
        latency_ms = int((time.time() - t0) * 1000)
        reqlog.append({
            "id": f"req_{int(time.time()*1000)}_{len(reqlog)+1}",
            "endpoint": "list_delegates",
            "gmail_account_id": acct.get("id") if acct else None,
            "status": status,
            "error_code": code,
            "error_message": message,
            "latency_ms": latency_ms,
            "created_at": now
        })
        _save("request_logs.json", reqlog)

    if includeDeleted is not None and not isinstance(includeDeleted, bool):
        _log("error", "VALIDATION_ERROR", "includeDeleted must be a boolean")
        return _err("VALIDATION_ERROR", "includeDeleted must be a boolean")

    if not acct:
        _log("error", "UNAUTHORIZED", "No authenticated Gmail account context available")
        return _err("UNAUTHORIZED", "No authenticated Gmail account context available")

    # ---- quota enforcement (settings read) ----
    # Heuristic: 10,000 settings ops/day/account; 60/min/account.
    one_min_ago = (datetime.datetime.utcnow() - datetime.timedelta(minutes=1)).replace(microsecond=0).isoformat() + "Z"
    one_day_ago = (datetime.datetime.utcnow() - datetime.timedelta(days=1)).replace(microsecond=0).isoformat() + "Z"
    aid = acct["id"]

    def _ts_ge(a, b):
        # ISO Z strings comparable lexicographically if same format.
        return isinstance(a, str) and isinstance(b, str) and a >= b

    last_min = 0
    last_day = 0
    for r in reqlog:
        if not isinstance(r, dict):
            continue
        if r.get("gmail_account_id") != aid:
            continue
        ep = r.get("endpoint")
        if ep not in ("list_delegates", "get_filter", "create_filter", "delete_filter"):
            continue
        ts = r.get("created_at")
        if _ts_ge(ts, one_min_ago):
            last_min += 1
        if _ts_ge(ts, one_day_ago):
            last_day += 1

    if last_min >= 60:
        _log("error", "RATE_LIMIT", "Rate limit exceeded for settings operations")
        return _err("RATE_LIMIT", "Rate limit exceeded for settings operations")
    if last_day >= 10000:
        _log("error", "QUOTA_EXCEEDED", "Daily quota exceeded for settings operations")
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded for settings operations")

    entities = _load("gmail_settings_entities.json")
    if not isinstance(entities, list):
        entities = []

    delegates = []
    for e in entities:
        if not isinstance(e, dict):
            continue
        if e.get("gmail_account_id") != aid:
            continue
        if e.get("entity_type") != "delegate":
            continue
        st = e.get("status")
        if st == "deleted" and not includeDeleted:
            continue
        payload = e.get("payload") if isinstance(e.get("payload"), dict) else {}
        delegates.append({
            "delegateEmail": e.get("external_key"),
            "verificationStatus": st,
            "payload": payload
        })

    _log("ok")
    return {"delegates": delegates}

def create_filter(criteria, action, **_extra):
    import json, os, datetime, time, secrets, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0088000" if __import__("os").path.isdir("./environment_mix/0088000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, gmail_account_id=None, error_code=None, error_message=None):
        logs = _load("gmail_request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"grl_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "create_filter",
            "gmail_account_id": gmail_account_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        })
        _save("gmail_request_logs.json", logs)

    def _resolve_account():
        accts = _load("gmail_accounts.json")
        if not isinstance(accts, list): accts = []
        for st in ("active", "suspended"):
            for a in accts:
                if isinstance(a, dict) and a.get("id") and a.get("status") == st:
                    return a
        for a in accts:
            if isinstance(a, dict) and a.get("id") and a.get("status") != "disconnected":
                return a
        return None

    acct = _resolve_account()
    if not acct:
        _log("error", None, "UNAUTHORIZED", "No connected Gmail account context available.")
        return _err("UNAUTHORIZED", "No connected Gmail account context available.")
    gmail_account_id = acct["id"]

    if not isinstance(criteria, dict):
        _log("error", gmail_account_id, "VALIDATION_ERROR", "criteria must be an object.")
        return _err("VALIDATION_ERROR", "criteria must be an object.", field="criteria")
    if not isinstance(action, dict):
        _log("error", gmail_account_id, "VALIDATION_ERROR", "action must be an object.")
        return _err("VALIDATION_ERROR", "action must be an object.", field="action")

    # Validate criteria fields per schema (be permissive, but enforce enum/type where provided)
    allowed_size_comp = {"smaller", "larger"}
    if "sizeComparison" in criteria and criteria["sizeComparison"] is not None:
        if criteria["sizeComparison"] not in allowed_size_comp:
            _log("error", gmail_account_id, "VALIDATION_ERROR", "criteria.sizeComparison must be 'smaller' or 'larger'.")
            return _err("VALIDATION_ERROR", "criteria.sizeComparison must be 'smaller' or 'larger'.", field="criteria.sizeComparison")
    if "size" in criteria and criteria["size"] is not None:
        if not isinstance(criteria["size"], (int, float)) or criteria["size"] < 0:
            _log("error", gmail_account_id, "VALIDATION_ERROR", "criteria.size must be a non-negative number.")
            return _err("VALIDATION_ERROR", "criteria.size must be a non-negative number.", field="criteria.size")

    # Validate action label ids against existing labels in mailbox
    add_ids = action.get("addLabelIds")
    rem_ids = action.get("removeLabelIds")
    if add_ids is None: add_ids = []
    if rem_ids is None: rem_ids = []

    if not isinstance(add_ids, list) or any((not isinstance(x, str) or not x.strip()) for x in add_ids):
        _log("error", gmail_account_id, "VALIDATION_ERROR", "action.addLabelIds must be an array of strings.")
        return _err("VALIDATION_ERROR", "action.addLabelIds must be an array of strings.", field="action.addLabelIds")
    if not isinstance(rem_ids, list) or any((not isinstance(x, str) or not x.strip()) for x in rem_ids):
        _log("error", gmail_account_id, "VALIDATION_ERROR", "action.removeLabelIds must be an array of strings.")
        return _err("VALIDATION_ERROR", "action.removeLabelIds must be an array of strings.", field="action.removeLabelIds")

    add_ids = [x.strip() for x in add_ids]
    rem_ids = [x.strip() for x in rem_ids]
    both = set(add_ids).intersection(set(rem_ids))
    if both:
        _log("error", gmail_account_id, "VALIDATION_ERROR", "A label id cannot be both added and removed in the same filter.")
        return _err("VALIDATION_ERROR", "A label id cannot be both added and removed in the same filter.", conflict_label_ids=sorted(both))

    labels = _load("gmail_labels.json")
    if not isinstance(labels, list): labels = []
    active_label_ids = set()
    for l in labels:
        if isinstance(l, dict) and l.get("gmail_account_id") == gmail_account_id and l.get("status") == "active" and l.get("gmail_label_id"):
            active_label_ids.add(l.get("gmail_label_id"))

    for lid in add_ids + rem_ids:
        if lid not in active_label_ids:
            _log("error", gmail_account_id, "NOT_FOUND", "Label not found for this mailbox.")
            return _err("NOT_FOUND", "Label not found for this mailbox.", labelId=lid)

    # Create settings entity filter
    settings = _load("gmail_settings_entities.json")
    if not isinstance(settings, list): settings = []
    existing_ids = {s.get("id") for s in settings if isinstance(s, dict)}
    existing_keys = {(s.get("gmail_account_id"), s.get("entity_type"), s.get("external_key"), s.get("scope_key")) for s in settings if isinstance(s, dict)}

    def _gen_id(prefix):
        while True:
            v = prefix + "_" + secrets.token_hex(10)
            if v not in existing_ids:
                return v

    # Provider filter id (external_key) - generate and ensure uniqueness within mailbox
    def _gen_filter_key():
        while True:
            fid = "filter_" + secrets.token_hex(8)
            if (gmail_account_id, "filter", fid, None) not in existing_keys:
                return fid

    external_key = _gen_filter_key()
    row = {
        "id": _gen_id("gse"),
        "gmail_account_id": gmail_account_id,
        "entity_type": "filter",
        "external_key": external_key,
        "scope_key": None,
        "payload": {"criteria": criteria, "action": action},
        "status": "active",
        "is_default": None,
        "created_at": now,
        "updated_at": now,
    }
    settings.append(row)
    _save("gmail_settings_entities.json", settings)

    _log("success", gmail_account_id, None, None)
    return {"filter": {"id": external_key, **row["payload"]}}

def delete_filter(id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0088000" if __import__("os").path.isdir("./environment_mix/0088000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, gmail_account_id=None, error_code=None, error_message=None):
        logs = _load("gmail_request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"grl_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "delete_filter",
            "gmail_account_id": gmail_account_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        })
        _save("gmail_request_logs.json", logs)

    def _resolve_account_for_filter(filter_id):
        accts = _load("gmail_accounts.json")
        settings = _load("gmail_settings_entities.json")
        if not isinstance(accts, list): accts = []
        if not isinstance(settings, list): settings = []
        for a in accts:
            if not isinstance(a, dict): 
                continue
            if a.get("status") == "disconnected":
                continue
            aid = a.get("id")
            if not aid:
                continue
            for s in settings:
                if isinstance(s, dict) and s.get("gmail_account_id") == aid and s.get("entity_type") == "filter" and s.get("external_key") == filter_id:
                    if s.get("status") != "deleted":
                        return a
        for st in ("active", "suspended"):
            for a in accts:
                if isinstance(a, dict) and a.get("id") and a.get("status") == st:
                    return a
        for a in accts:
            if isinstance(a, dict) and a.get("id") and a.get("status") != "disconnected":
                return a
        return None

    if not isinstance(id, str) or not id.strip():
        acct = _resolve_account_for_filter(id if isinstance(id, str) else "")
        _log("error", acct.get("id") if acct else None, "VALIDATION_ERROR", "id must be a non-empty string.")
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")
    id = id.strip()

    acct = _resolve_account_for_filter(id)
    if not acct:
        _log("error", None, "UNAUTHORIZED", "No connected Gmail account context available.")
        return _err("UNAUTHORIZED", "No connected Gmail account context available.")
    gmail_account_id = acct["id"]

    settings = _load("gmail_settings_entities.json")
    if not isinstance(settings, list): settings = []

    idx = None
    row = None
    for i, s in enumerate(settings):
        if not isinstance(s, dict):
            continue
        if s.get("gmail_account_id") != gmail_account_id:
            continue
        if s.get("entity_type") == "filter" and s.get("external_key") == id:
            if s.get("status") != "deleted":
                idx = i
                row = s
            break

    if not row:
        _log("error", gmail_account_id, "NOT_FOUND", "Filter not found.")
        return _err("NOT_FOUND", "Filter not found.", id=id)

    # Lifecycle transition: active -> deleted
    settings[idx]["status"] = "deleted"
    settings[idx]["updated_at"] = now
    _save("gmail_settings_entities.json", settings)

    _log("success", gmail_account_id, None, None)
    return {}

