        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate
    if includeDeleted is not None and not isinstance(includeDeleted, bool):
        return _err("VALIDATION_ERROR", "includeDeleted must be a boolean when provided")

    # Ambient auth: pick a gmail account that can serve the call
    accounts = _load("gmail_accounts.json")
    acct = None
    for a in accounts:
        if isinstance(a, dict) and a.get("status") == "active":
            acct = a
            break
    # If none active, allow suspended to read settings? treat as unauthorized for service operations
    if acct is None:
        for a in accounts:
            if isinstance(a, dict) and a.get("status") in ("suspended",):
                acct = a
                break
    if acct is None:
        # log attempt
        logs = _load("gmail_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "list_filters",
            "gmail_account_id": None,
            "status": "UNAUTHORIZED",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("gmail_request_logs.json", logs)
        return _err("UNAUTHORIZED", "Not authenticated")

    gmail_account_id = acct.get("id")

    # Quota / rate limiting (settings reads)
    logs = _load("gmail_request_logs.json")
    if not isinstance(logs, list):
        logs = []
    window_s = 60
    read_limit_per_min = 120  # service-side safe default
    cutoff = time.time() - window_s
    read_count = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("gmail_account_id") != gmail_account_id:
            continue
        if r.get("endpoint") != "list_filters":
            continue
        ts = r.get("timestamp")
        if isinstance(ts, str):
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                if dt.timestamp() >= cutoff:
                    if r.get("status") == "OK":
                        read_count += 1
            except Exception:
                continue
    if read_count >= read_limit_per_min:
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "list_filters",
            "gmail_account_id": gmail_account_id,
            "status": "QUOTA_EXCEEDED",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("gmail_request_logs.json", logs)
        return _err("QUOTA_EXCEEDED", "Settings read quota exceeded")

    entities = _load("gmail_settings_entities.json")
    if not isinstance(entities, list):
        entities = []

    rows = []
    for e in entities:
        if not isinstance(e, dict):
            continue
        if e.get("gmail_account_id") != gmail_account_id:
            continue
        if e.get("entity_type") != "filter":
            continue
        if not includeDeleted and e.get("status") == "deleted":
            continue
        # Represent as Gmail-like filter resource
        payload = e.get("payload") if isinstance(e.get("payload"), dict) else {}
        rows.append({
            "id": e.get("external_key"),
            "criteria": payload.get("criteria", {}),
