            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("gmail_request_logs.json", logs)
        return _err("QUOTA_EXCEEDED", "Settings mutation quota exceeded")

    entities = _load("gmail_settings_entities.json")
    if not isinstance(entities, list):
        entities = []

    # Conflict check: unique(gmail_account_id, entity_type, external_key, scope_key)
    for e in entities:
        if not isinstance(e, dict):
            continue
        if e.get("gmail_account_id") == gmail_account_id and e.get("entity_type") == "forwarding_address":
            if e.get("external_key") == forwardingEmail and (e.get("scope_key") is None):
                if e.get("status") != "deleted":
                    logs.append({
                        "id": f"req_{int(time.time()*1000)}",
                        "endpoint": "create_forwarding_address",
                        "gmail_account_id": gmail_account_id,
                        "status": "CONFLICT",
                        "timestamp": now,
                        "latency_ms": int((time.time() - t0) * 1000)
                    })
                    _save("gmail_request_logs.json", logs)
                    return _err("CONFLICT", "Forwarding address already exists")
                # If deleted, allow re-create by resurrecting (idempotent-ish)
                e["status"] = "pending_verification"
                e["payload"] = {"forwardingEmail": forwardingEmail, "verificationStatus": "pending"}
                e["updated_at"] = now
                # keep created_at as-is
                _save("gmail_settings_entities.json", entities)
                logs.append({
                    "id": f"req_{int(time.time()*1000)}",
                    "endpoint": "create_forwarding_address",
                    "gmail_account_id": gmail_account_id,
                    "status": "OK",
                    "timestamp": now,
                    "latency_ms": int((time.time() - t0) * 1000)
                })
                _save("gmail_request_logs.json", logs)
                return {
                    "forwardingEmail": forwardingEmail,
                    "verificationStatus": "pending"
                }

    # Create new row
    new_id = f"gse_{int(time.time()*1000)}"
    row = {
        "id": new_id,
        "gmail_account_id": gmail_account_id,
        "entity_type": "forwarding_address",
        "external_key": forwardingEmail,
        "scope_key": None,
        "payload": {
            "forwardingEmail": forwardingEmail,
            "verificationStatus": "pending"
        },
        "status": "pending_verification",
        "is_default": None,
        "created_at": now,
        "updated_at": now
    }
    entities.append(row)
    _save("gmail_settings_entities.json", entities)

    logs.append({
        "id": f"req_{int(time.time()*1000)}",
        "endpoint": "create_forwarding_address",
        "gmail_account_id": gmail_account_id,
        "status": "OK",
        "timestamp": now,
        "latency_ms": int((time.time() - t0) * 1000)
    })
    _save("gmail_request_logs.json", logs)

    return {
        "forwardingEmail": forwardingEmail,
        "verificationStatus": "pending"
    }

def delete_forwarding_address(forwardingEmail, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0088000" if __import__("os").path.isdir("./environment_mix/0088000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(forwardingEmail, str) or not forwardingEmail.strip():
        return _err("VALIDATION_ERROR", "forwardingEmail is required")
    forwardingEmail = forwardingEmail.strip()
    if not re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", forwardingEmail):
        return _err("VALIDATION_ERROR", "forwardingEmail must be a valid email address")

    accounts = _load("gmail_accounts.json")
    acct = None
    for a in accounts:
        if isinstance(a, dict) and a.get("status") == "active":
            acct = a
            break
    if acct is None:
        logs = _load("gmail_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "delete_forwarding_address",
            "gmail_account_id": None,
            "status": "UNAUTHORIZED",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("gmail_request_logs.json", logs)
        return _err("UNAUTHORIZED", "Not authenticated")

    gmail_account_id = acct.get("id")

    logs = _load("gmail_request_logs.json")
    if not isinstance(logs, list):
        logs = []
    window_s = 60
    mutation_limit_per_min = 30
    cutoff = time.time() - window_s
    mut_count = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("gmail_account_id") != gmail_account_id:
            continue
        if r.get("endpoint") not in ("create_forwarding_address", "delete_forwarding_address"):
            continue
        ts = r.get("timestamp")
        if isinstance(ts, str):
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                if dt.timestamp() >= cutoff and r.get("status") == "OK":
                    mut_count += 1
            except Exception:
                continue
    if mut_count >= mutation_limit_per_min:
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "delete_forwarding_address",
            "gmail_account_id": gmail_account_id,
            "status": "QUOTA_EXCEEDED",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("gmail_request_logs.json", logs)
        return _err("QUOTA_EXCEEDED", "Settings mutation quota exceeded")

    entities = _load("gmail_settings_entities.json")
    if not isinstance(entities, list):
        entities = []

    target = None
    for e in entities:
        if not isinstance(e, dict):
            continue
        if e.get("gmail_account_id") != gmail_account_id:
            continue
        if e.get("entity_type") != "forwarding_address":
            continue
        if e.get("external_key") != forwardingEmail or e.get("scope_key") is not None:
            continue
        if e.get("status") == "deleted":
            continue
        target = e
        break

    if target is None:
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "delete_forwarding_address",
            "gmail_account_id": gmail_account_id,
            "status": "NOT_FOUND",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("gmail_request_logs.json", logs)
        return _err("NOT_FOUND", "Forwarding address not found")

    # Transition to deleted (must be legal)
    # lifecycle for settings_entities: active/pending_verification -> deleted
    if target.get("status") not in ("active", "pending_verification", "stopped"):
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "delete_forwarding_address",
            "gmail_account_id": gmail_account_id,
            "status": "INVALID_TRANSITION",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("gmail_request_logs.json", logs)
        return _err("INVALID_TRANSITION", f"Cannot delete forwarding address from status '{target.get('status')}'")

    target["status"] = "deleted"
    target["updated_at"] = now
    # Keep payload but mark deletedAt for audit
    if isinstance(target.get("payload"), dict):
        target["payload"]["deletedAt"] = now
    else:
        target["payload"] = {"forwardingEmail": forwardingEmail, "deletedAt": now}

    _save("gmail_settings_entities.json", entities)

    logs.append({
        "id": f"req_{int(time.time()*1000)}",
        "endpoint": "delete_forwarding_address",
        "gmail_account_id": gmail_account_id,
        "status": "OK",
        "timestamp": now,
        "latency_ms": int((time.time() - t0) * 1000)
    })
    _save("gmail_request_logs.json", logs)

    # Empty success response
    return {}

