def list_forwarding_addresses(maxResults=None, pageToken=None, **_extra):
    import json, os, datetime, time, base64, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0088000" if __import__("os").path.isdir("./environment_mix/0088000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_forwarding_addresses"

    # ---- helpers ----
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, gmail_account_id=None, error_code=None):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{time.time_ns()}".encode()).hexdigest()[:24],
            "timestamp": _now(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": credential_id,
            "gmail_account_id": gmail_account_id,
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save("request_logs.json", logs)

    def _get_context_gmail_account():
        # Ambient auth: find any gmail_account that can serve calls (active preferred).
        accounts = _load("gmail_accounts.json")
        if not isinstance(accounts, list):
            return None
        # Prefer active, else suspended. disconnected should not serve.
        for st in ("active", "suspended"):
            for a in accounts:
                if isinstance(a, dict) and a.get("status") == st and isinstance(a.get("id"), str):
                    return a
        return None

    def _decode_token(tok):
        try:
            data = base64.urlsafe_b64decode(tok.encode("utf-8") + b"===").decode("utf-8")
            return json.loads(data)
        except Exception:
            return None

    def _encode_token(obj):
        b = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(b).decode("utf-8").rstrip("=")

    # ---- validate inputs ----
    if maxResults is None:
        max_results = 50
    else:
        if not isinstance(maxResults, (int, float)) or isinstance(maxResults, bool):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "maxResults must be a number")
        if int(maxResults) != maxResults:
            # tolerate floats that are integral
            if not (isinstance(maxResults, float) and maxResults.is_integer()):
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "maxResults must be an integer value")
        max_results = int(maxResults)
        if max_results < 1 or max_results > 500:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "maxResults must be between 1 and 500")

    if pageToken is not None and not isinstance(pageToken, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "pageToken must be a string")

    acct = _get_context_gmail_account()
    if not acct:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authorized Gmail account context available")

    gmail_account_id = acct["id"]

    # ---- quota / rate limiting (if usage logs schema exists) ----
    # Simple enforcement using request_logs.json only (if missing, it will be created).
    logs = _load("request_logs.json")
    if isinstance(logs, list):
        now = datetime.datetime.utcnow()
        # rate limit: 120 requests/min per gmail_account_id
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("gmail_account_id") != gmail_account_id:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= window_start:
                cnt += 1
        if cnt >= 120:
            _log("error", gmail_account_id=gmail_account_id, error_code="RATE_LIMIT")
            return _err("RATE_LIMIT", "Rate limit exceeded")

        # daily quota: 10,000 requests/day per gmail_account_id
        day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
        day_cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("gmail_account_id") != gmail_account_id:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= day_start:
                day_cnt += 1
        if day_cnt >= 10000:
            _log("error", gmail_account_id=gmail_account_id, error_code="QUOTA_EXCEEDED")
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

    # ---- load forwarding addresses ----
    entities = _load("gmail_settings_entities.json")
    if not isinstance(entities, list):
        entities = []

    # Constraints for pageToken for this tool: entity_type fixed, status filter fixed.
    constraint = {
        "tool": endpoint,
        "gmail_account_id": gmail_account_id,
        "entity_type": "forwarding_address",
        "exclude_status": ["deleted"],
    }

    start = 0
    if pageToken:
        tok = _decode_token(pageToken)
        if not isinstance(tok, dict):
            _log("error", gmail_account_id=gmail_account_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid pageToken")
        # Validate constraints match
        for k, v in constraint.items():
            if tok.get(k) != v:
                _log("error", gmail_account_id=gmail_account_id, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "pageToken does not match request constraints")
        start = tok.get("start", 0)
        if not isinstance(start, int) or start < 0:
            _log("error", gmail_account_id=gmail_account_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid pageToken")

    rows = []
    for e in entities:
        if not isinstance(e, dict):
            continue
        if e.get("gmail_account_id") != gmail_account_id:
            continue
        if e.get("entity_type") != "forwarding_address":
            continue
        if e.get("status") == "deleted":
            continue
        payload = e.get("payload")
        if not isinstance(payload, dict):
            payload = {}
        # external_key = forwardingEmail
        rows.append({
            "forwardingEmail": e.get("external_key"),
            **payload
        })

    # stable sort by forwardingEmail
    rows.sort(key=lambda r: ("" if r.get("forwardingEmail") is None else str(r.get("forwardingEmail")).lower()))

    total = len(rows)
    page = rows[start:start + max_results]
    next_token = None
    next_start = start + len(page)
    if next_start < total:
        tok = dict(constraint)
        tok["start"] = next_start
        next_token = _encode_token(tok)

    _log("success", gmail_account_id=gmail_account_id)
    return {
        "forwardingAddresses": page,
        "nextPageToken": next_token,
        "resultSizeEstimate": total,
    }

