            if r.get("gmail_account_id") != gmail_account_id:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= window_start:
                cnt += 1
        if cnt >= 120:
            _log("error", gmail_account_id=gmail_account_id, error_code="RATE_LIMIT")
            return _err("RATE_LIMIT", "Rate limit exceeded")

        day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
        day_cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("gmail_account_id") != gmail_account_id:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= day_start:
                day_cnt += 1
        if day_cnt >= 10000:
            _log("error", gmail_account_id=gmail_account_id, error_code="QUOTA_EXCEEDED")
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

    entities = _load("gmail_settings_entities.json")
    if not isinstance(entities, list):
        entities = []

    # conflict: existing send_as with same external_key not deleted
    for e in entities:
        if not isinstance(e, dict):
            continue
        if e.get("gmail_account_id") != gmail_account_id:
            continue
        if e.get("entity_type") != "send_as":
            continue
        if e.get("external_key") == sendAsEmail and e.get("status") != "deleted":
            _log("error", gmail_account_id=gmail_account_id, error_code="CONFLICT")
            return _err("CONFLICT", "A send-as alias with this sendAsEmail already exists")

    # cannot create alias with same as primary mailbox email if it already exists as primary send_as
    # Here we treat gmail_accounts.email_address as primary mailbox; if same email, conflict unless no send_as exists yet.
    if isinstance(acct.get("email_address"), str) and acct["email_address"].lower() == sendAsEmail.lower():
        # if there is an active primary send_as already for this email, conflict; else allow create as primary.
        for e in entities:
            if not isinstance(e, dict):
                continue
            if e.get("gmail_account_id") != gmail_account_id:
                continue
            if e.get("entity_type") != "send_as":
                continue
            if (e.get("external_key") or "").lower() == sendAsEmail.lower() and e.get("status") != "deleted":
                _log("error", gmail_account_id=gmail_account_id, error_code="CONFLICT")
                return _err("CONFLICT", "Alias conflicts with existing account configuration")

    # build payload
    payload = {}
    if displayName is not None:
        payload["displayName"] = displayName
    if replyToAddress is not None:
        payload["replyToAddress"] = replyToAddress
    if signature is not None:
        payload["signature"] = signature
    if treatAsAlias is not None:
        payload["treatAsAlias"] = treatAsAlias
    if isPrimary is not None:
        payload["isPrimary"] = isPrimary

    # if setting isPrimary true, ensure no other non-deleted send_as remains primary; update them (legal update).
    # This mirrors provider behavior where primary is unique.
    if isPrimary is True:
        changed = False
        for e in entities:
            if not isinstance(e, dict):
                continue
            if e.get("gmail_account_id") != gmail_account_id or e.get("entity_type") != "send_as":
                continue
            if e.get("status") == "deleted":
                continue
            pl = e.get("payload")
            if isinstance(pl, dict) and pl.get("isPrimary") is True:
                pl["isPrimary"] = False
                e["payload"] = pl
                e["updated_at"] = _now()
                changed = True
        if changed:
            _save("gmail_settings_entities.json", entities)

    now_s = _now()
    row = {
        "id": _gen_id("gse"),
        "gmail_account_id": gmail_account_id,
        "entity_type": "send_as",
        "external_key": sendAsEmail,
        "scope_key": None,
        "payload": payload,
        "status": "active",
        "is_default": None,
        "created_at": now_s,
        "updated_at": now_s,
    }

    entities.append(row)
    _save("gmail_settings_entities.json", entities)

    # Response: send-as resource
    resource = {
        "sendAsEmail": sendAsEmail,
        **payload,
    }
    _log("success", gmail_account_id=gmail_account_id)
    return resource

