def list_send_as(maxResults=None, pageToken=None, **_extra):
    import json, os, datetime, time, base64, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0088000" if __import__("os").path.isdir("./environment_mix/0088000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "service": "gmail_mcp",
            "endpoint": "list_send_as",
            "gmail_account_id": _acct["id"] if isinstance(_acct, dict) else None,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "meta": meta or {},
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # Resolve ambient auth context: pick a workable active account
    accounts = _load("gmail_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    _acct = None
    for a in accounts:
        if isinstance(a, dict) and a.get("status") == "active":
            _acct = a
            break
    if _acct is None:
        # no possible authenticated context
        # (still log)
        dummy = {"id": None}
        _acct = dummy
        _log("error", "UNAUTHORIZED", "No active Gmail account available for this call.")
        return _err("UNAUTHORIZED", "No active Gmail account available for this call.")

    # Validate maxResults and pageToken
    if maxResults is None:
        page_size = 50
    else:
        if not isinstance(maxResults, (int, float)) or isinstance(maxResults, bool):
            _log("error", "VALIDATION_ERROR", "maxResults must be a number.")
            return _err("VALIDATION_ERROR", "maxResults must be a number.")
        if int(maxResults) != maxResults:
            # disallow fractional
            _log("error", "VALIDATION_ERROR", "maxResults must be an integer.")
            return _err("VALIDATION_ERROR", "maxResults must be an integer.")
        page_size = int(maxResults)
        if page_size <= 0:
            _log("error", "VALIDATION_ERROR", "maxResults must be positive.")
            return _err("VALIDATION_ERROR", "maxResults must be positive.")
        if page_size > 500:
            _log("error", "VALIDATION_ERROR", "maxResults must be between 1 and 500.")
            return _err("VALIDATION_ERROR", "maxResults must be between 1 and 500.")

    expected = {"v": 1, "gmail_account_id": _acct["id"], "tool": "list_send_as"}
    start = 0
    if pageToken is not None:
        if not isinstance(pageToken, str) or not pageToken.strip():
            _log("error", "VALIDATION_ERROR", "pageToken must be a non-empty string when provided.")
            return _err("VALIDATION_ERROR", "pageToken must be a non-empty string when provided.")
        try:
            raw = base64.urlsafe_b64decode(pageToken.encode("utf-8") + b"===")
            tok = json.loads(raw.decode("utf-8"))
        except Exception:
            _log("error", "VALIDATION_ERROR", "Invalid pageToken.")
            return _err("VALIDATION_ERROR", "Invalid pageToken.")
        if not isinstance(tok, dict):
            _log("error", "VALIDATION_ERROR", "Invalid pageToken.")
            return _err("VALIDATION_ERROR", "Invalid pageToken.")
        for k, v in expected.items():
            if tok.get(k) != v:
                _log("error", "VALIDATION_ERROR", "pageToken does not match this request context.")
                return _err("VALIDATION_ERROR", "pageToken does not match this request context.")
        if not isinstance(tok.get("start"), int) or tok["start"] < 0:
            _log("error", "VALIDATION_ERROR", "Invalid pageToken cursor.")
            return _err("VALIDATION_ERROR", "Invalid pageToken cursor.")
        start = tok["start"]

    entities = _load("gmail_settings_entities.json")
    if not isinstance(entities, list):
        entities = []

    # Filter to mailbox + send_as, excluding deleted by default per rules
    rows = []
    for e in entities:
        if not isinstance(e, dict):
            continue
        if e.get("gmail_account_id") != _acct["id"]:
            continue
        if e.get("entity_type") != "send_as":
            continue
        if e.get("status") == "deleted":
            continue
        payload = e.get("payload") if isinstance(e.get("payload"), dict) else {}
        # Provide a Gmail-like sendAs resource view based on payload + keys
        send_as = {
            "sendAsEmail": e.get("external_key"),
            "displayName": payload.get("displayName"),
            "replyToAddress": payload.get("replyToAddress"),
            "signature": payload.get("signature"),
            "isPrimary": payload.get("isPrimary"),
            "treatAsAlias": payload.get("treatAsAlias"),
            "isVerified": payload.get("isVerified"),
        }
        # include a few useful fields when present
        for k in ("smtpMsa", "verificationStatus", "replyToAddress", "displayName"):
            if k in payload and k not in send_as:
                send_as[k] = payload.get(k)
        rows.append(send_as)

    # Stable ordering: primary first then by email
    def _key(r):
        return (0 if r.get("isPrimary") else 1, (r.get("sendAsEmail") or "").lower())
    rows.sort(key=_key)

    total = len(rows)
    page = rows[start:start + page_size]
    next_token = None
    if start + page_size < total:
        tok = {"v": 1, "tool": "list_send_as", "gmail_account_id": _acct["id"], "start": start + page_size}
        next_token = base64.urlsafe_b64encode(json.dumps(tok, separators=(",", ":")).encode("utf-8")).decode("utf-8")

    resp = {
        "sendAs": page,
        "nextPageToken": next_token,
        "resultSizeEstimate": len(page),
        "total": total,
    }
    _log("ok", meta={"returned": len(page), "total": total, "has_more": bool(next_token)})
    return resp

