        changed = True
        if isPrimary is True:
            # unset others for this mailbox
            for j, other in enumerate(entities):
                if j == idx or not isinstance(other, dict):
                    continue
                if other.get("gmail_account_id") != _acct["id"]:
                    continue
                if other.get("entity_type") != "send_as":
