    # Effect check: ensure something actually changed vs stored editable fields
    def _editable(p):
        return {k: p.get(k) for k in ("displayName", "replyToAddress", "signature", "isPrimary", "treatAsAlias")}
    if _editable(old_payload) == _editable(new_payload):
