            _acct = a
            break
    if _acct is None:
        _acct = {"id": None}
        _log("error", "UNAUTHORIZED", "No active Gmail account available for this call.")
        return _err("UNAUTHORIZED", "No active Gmail account available for this call.")

    # Validate sendAsEmail
    if not isinstance(sendAsEmail, str) or not sendAsEmail.strip():
        _log("error", "VALIDATION_ERROR", "sendAsEmail is required and must be a non-empty string.")
        return _err("VALIDATION_ERROR", "sendAsEmail is required and must be a non-empty string.")
    sendAsEmail = sendAsEmail.strip()
