    if not isinstance(entities, list):
        entities = []

    idx = None
    for i, e in enumerate(entities):
        if not isinstance(e, dict):
            continue
        if e.get("gmail_account_id") != _acct["id"]:
            continue
        if e.get("entity_type") != "send_as":
            continue
        if e.get("external_key") == sendAsEmail and e.get("status") != "deleted":
            idx = i
            break
    if idx is None:
        _log("error", "NOT_FOUND", "Send-as alias not found.")
        return _err("NOT_FOUND", "Send-as alias not found.")

    e = entities[idx]
    # Business rule: verify_send_as transitions status to pending_verification and records timestamp
    cur = e.get("status")
    allowed = {"active": ["pending_verification", "deleted", "stopped"], "pending_verification": ["active", "deleted"], "stopped": ["active", "deleted"], "deleted": []}
    if cur == "pending_verification":
        _log("error", "CONFLICT", "Verification already initiated for this alias.")
        return _err("CONFLICT", "Verification already initiated for this alias.")
    if cur not in allowed or "pending_verification" not in allowed.get(cur, []):
        _log("error", "INVALID_TRANSITION", f"Cannot initiate verification from status '{cur}'.")
        return _err("INVALID_TRANSITION", f"Cannot initiate verification from status '{cur}'.")

    payload = e.get("payload") if isinstance(e.get("payload"), dict) else {}
    if payload.get("isVerified") is True:
        _log("error", "CONFLICT", "Alias is already verified.")
        return _err("CONFLICT", "Alias is already verified.")

    # Mutate
    payload["verificationSentAt"] = _now()
    payload["verificationStatus"] = "sent"
    e["payload"] = payload
    e["status"] = "pending_verification"
    e["updated_at"] = _now()
    entities[idx] = e
    _save("gmail_settings_entities.json", entities)

    _log("ok", meta={"sendAsEmail": sendAsEmail})
    return {"status": "ok"}

def delete_smime_info(sendAsEmail, id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0088000" if __import__("os").path.isdir("./environment_mix/0088000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, gmail_account_id=None, error_code=None, error_message=None):
        logs = _load("gmail_request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"grl_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "delete_smime_info",
            "gmail_account_id": gmail_account_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        })
        _save("gmail_request_logs.json", logs)

    def _resolve_account_for_smime(send_as_email, smime_id):
        accts = _load("gmail_accounts.json")
        settings = _load("gmail_settings_entities.json")
        if not isinstance(accts, list): accts = []
        if not isinstance(settings, list): settings = []
        for a in accts:
            if not isinstance(a, dict):
                continue
            if a.get("status") == "disconnected":
                continue
            aid = a.get("id")
            if not aid:
                continue
            for s in settings:
                if not isinstance(s, dict):
                    continue
                if s.get("gmail_account_id") != aid:
                    continue
                if s.get("entity_type") == "smime_info" and s.get("scope_key") == send_as_email and s.get("external_key") == smime_id:
                    if s.get("status") != "deleted":
                        return a
        for st in ("active", "suspended"):
            for a in accts:
                if isinstance(a, dict) and a.get("id") and a.get("status") == st:
                    return a
        for a in accts:
            if isinstance(a, dict) and a.get("id") and a.get("status") != "disconnected":
                return a
        return None

    if not isinstance(sendAsEmail, str) or not sendAsEmail.strip():
        acct = _resolve_account_for_smime(sendAsEmail if isinstance(sendAsEmail, str) else "", id if isinstance(id, str) else "")
        _log("error", acct.get("id") if acct else None, "VALIDATION_ERROR", "sendAsEmail must be a non-empty string.")
        return _err("VALIDATION_ERROR", "sendAsEmail must be a non-empty string.", field="sendAsEmail")
    if not isinstance(id, str) or not id.strip():
        acct = _resolve_account_for_smime(sendAsEmail.strip() if isinstance(sendAsEmail, str) else "", id if isinstance(id, str) else "")
        _log("error", acct.get("id") if acct else None, "VALIDATION_ERROR", "id must be a non-empty string.")
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")
    sendAsEmail = sendAsEmail.strip()
    id = id.strip()

    acct = _resolve_account_for_smime(sendAsEmail, id)
    if not acct:
        _log("error", None, "UNAUTHORIZED", "No connected Gmail account context available.")
        return _err("UNAUTHORIZED", "No connected Gmail account context available.")
    gmail_account_id = acct["id"]

    settings = _load("gmail_settings_entities.json")
    if not isinstance(settings, list): settings = []

    idx = None
    row = None
    for i, s in enumerate(settings):
        if not isinstance(s, dict):
            continue
        if s.get("gmail_account_id") != gmail_account_id:
            continue
        if s.get("entity_type") == "smime_info" and s.get("scope_key") == sendAsEmail and s.get("external_key") == id:
            idx = i
            row = s
            break

    if not row or row.get("status") == "deleted":
        _log("error", gmail_account_id, "NOT_FOUND", "S/MIME config not found.")
        return _err("NOT_FOUND", "S/MIME config not found.", sendAsEmail=sendAsEmail, id=id)

    # If default, allow deletion but clear default; caller can set a new default later.
    settings[idx]["status"] = "deleted"
    settings[idx]["is_default"] = False
    settings[idx]["updated_at"] = now
    _save("gmail_settings_entities.json", settings)

    _log("success", gmail_account_id, None, None)
    return {}

def get_smime_info(sendAsEmail, id, **_extra):
