        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()

    accounts = _load("gmail_accounts.json")
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("status") == "active"), None)
    gmail_account_id = acct.get("id") if acct else None
    settings = _load("gmail_settings_entities.json")

    def _log(status, error_code=None):
        nonlocal accounts, acct
        ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        latency_ms = int((time.time() - started) * 1000)
        if not acct:
            return
        for a in accounts:
            if isinstance(a, dict) and a.get("id") == gmail_account_id:
                acct = a
                break
        if acct is None:
            return
        usage = acct.get("usage")
        if not isinstance(usage, dict):
            usage = {}
            acct["usage"] = usage
        logs = usage.get("request_log")
        if not isinstance(logs, list):
            logs = []
            usage["request_log"] = logs
        logs.append({
            "endpoint": "get_smime_info",
            "credential_used": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": ts
        })
        usage["total_calls"] = int(usage.get("total_calls") or 0) + 1
        if len(logs) > 2000:
            usage["request_log"] = logs[-2000:]
        _save("gmail_accounts.json", accounts)

    if not gmail_account_id:
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authorized Gmail account context is available for this request.")

    def _check_limits():
        usage = acct.get("usage")
        if not isinstance(usage, dict):
            return None
        logs = usage.get("request_log")
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.utcnow()
        one_min_ago = now - datetime.timedelta(minutes=1)
        per_min = 0
        for r in logs[-500:]:
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str) or not ts.endswith("Z"):
                continue
            try:
                t = datetime.datetime.fromisoformat(ts[:-1])
            except Exception:
                continue
            if t >= one_min_ago:
                per_min += 1
        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        day_ago = now - datetime.timedelta(days=1)
        per_day = 0
        for r in logs[-2000:]:
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str) or not ts.endswith("Z"):
                continue
            try:
                t = datetime.datetime.fromisoformat(ts[:-1])
            except Exception:
                continue
            if t >= day_ago:
                per_day += 1
        if per_day >= 10000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    lim_err = _check_limits()
    if lim_err:
        _log("error", lim_err["error"]["code"])
        return lim_err

    if not isinstance(sendAsEmail, str) or not sendAsEmail.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sendAsEmail is required and must be a non-empty string.", field="sendAsEmail")
