    sendAsEmail = sendAsEmail.strip()
    id = id.strip()

    # Require send-as alias exist
    sendas = next(
        (e for e in settings
         if isinstance(e, dict)
         and e.get("gmail_account_id") == gmail_account_id
         and e.get("entity_type") == "send_as"
         and e.get("external_key") == sendAsEmail
         and e.get("status") != "deleted"),
        None
    )
    if not sendas:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Send-as alias not found.", sendAsEmail=sendAsEmail)

    smime = next(
        (e for e in settings
         if isinstance(e, dict)
         and e.get("gmail_account_id") == gmail_account_id
         and e.get("entity_type") == "smime_info"
         and e.get("scope_key") == sendAsEmail
         and e.get("external_key") == id
         and e.get("status") != "deleted"),
        None
    )
    if not smime:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "S/MIME config not found.", sendAsEmail=sendAsEmail, id=id)

    payload = smime.get("payload") if isinstance(smime.get("payload"), dict) else {}
    # Return resource; do not leak pkcs12 or encryptedKeyPassword (still stored at rest)
    resource = {
        "id": smime.get("external_key"),
        "sendAsEmail": smime.get("scope_key"),
        "isDefault": bool(smime.get("is_default")) if smime.get("is_default") is not None else False,
        "status": smime.get("status"),
