    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()

    accounts = _load("gmail_accounts.json")
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("status") == "active"), None)
    gmail_account_id = acct.get("id") if acct else None
    settings = _load("gmail_settings_entities.json")

    def _log(status, error_code=None):
        nonlocal accounts, acct
        ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        latency_ms = int((time.time() - started) * 1000)
        if not acct:
            return
        for a in accounts:
            if isinstance(a, dict) and a.get("id") == gmail_account_id:
                acct = a
                break
        if acct is None:
            return
        usage = acct.get("usage")
        if not isinstance(usage, dict):
            usage = {}
            acct["usage"] = usage
        logs = usage.get("request_log")
        if not isinstance(logs, list):
            logs = []
            usage["request_log"] = logs
        logs.append({
            "endpoint": "insert_smime_info",
            "credential_used": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": ts
        })
        usage["total_calls"] = int(usage.get("total_calls") or 0) + 1
        if len(logs) > 2000:
            usage["request_log"] = logs[-2000:]
        _save("gmail_accounts.json", accounts)

    if not gmail_account_id:
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authorized Gmail account context is available for this request.")

    def _check_limits():
        usage = acct.get("usage")
        if not isinstance(usage, dict):
            return None
        logs = usage.get("request_log")
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.utcnow()
        one_min_ago = now - datetime.timedelta(minutes=1)
        per_min = 0
        for r in logs[-500:]:
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str) or not ts.endswith("Z"):
                continue
            try:
                t = datetime.datetime.fromisoformat(ts[:-1])
            except Exception:
                continue
            if t >= one_min_ago:
                per_min += 1
        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        day_ago = now - datetime.timedelta(days=1)
        per_day = 0
        for r in logs[-2000:]:
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str) or not ts.endswith("Z"):
                continue
            try:
                t = datetime.datetime.fromisoformat(ts[:-1])
            except Exception:
                continue
            if t >= day_ago:
                per_day += 1
        if per_day >= 10000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    lim_err = _check_limits()
    if lim_err:
        _log("error", lim_err["error"]["code"])
        return lim_err

    # Validate inputs
    if not isinstance(sendAsEmail, str) or not sendAsEmail.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sendAsEmail is required and must be a non-empty string.", field="sendAsEmail")
    if not isinstance(encryptedKeyPassword, str) or not encryptedKeyPassword.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "encryptedKeyPassword is required and must be a non-empty string.", field="encryptedKeyPassword")
    if not isinstance(pkcs12, str) or not pkcs12.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "pkcs12 is required and must be a non-empty string.", field="pkcs12")
    sendAsEmail = sendAsEmail.strip()
    encryptedKeyPassword = encryptedKeyPassword.strip()
    pkcs12 = pkcs12.strip()

    # Require send-as alias exist
    sendas = next(
        (e for e in settings
         if isinstance(e, dict)
         and e.get("gmail_account_id") == gmail_account_id
         and e.get("entity_type") == "send_as"
         and e.get("external_key") == sendAsEmail
         and e.get("status") != "deleted"),
        None
    )
    if not sendas:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Send-as alias not found.", sendAsEmail=sendAsEmail)

    # Validate pkcs12 is base64 decodable (best-effort offline)
    try:
        # Accept standard base64; many clients provide base64 (not base64url) for pkcs12
        decoded = base64.b64decode(pkcs12, validate=False)
    except Exception:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "pkcs12 must be base64-encoded PKCS#12 bytes.", field="pkcs12")
    if not decoded or len(decoded) < 32:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "pkcs12 content appears invalid or too small to be a PKCS#12 bundle.", field="pkcs12")

    # Create immutable id (provider-like) and ensure uniqueness per (account, alias)
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    # Use a deterministic-ish component plus randomness to avoid collisions
    entropy = secrets.token_hex(12)
    digest = hashlib.sha256(decoded[:256] + entropy.encode("utf-8")).hexdigest()[:24]
    smime_id = f"smime_{digest}"

    # Enforce unique(gmail_account_id, entity_type, external_key, scope_key)
    for e in settings:
        if not isinstance(e, dict):
            continue
        if e.get("gmail_account_id") == gmail_account_id and e.get("entity_type") == "smime_info" and e.get("scope_key") == sendAsEmail and e.get("external_key") == smime_id:
            # extremely unlikely; regenerate once
            entropy2 = secrets.token_hex(12)
            digest2 = hashlib.sha256(decoded[:256] + entropy2.encode("utf-8")).hexdigest()[:24]
            smime_id = f"smime_{digest2}"
            break

    # Create row id for collection
    row_id = "gse_" + secrets.token_hex(12)

    # Store encryptedKeyPassword and pkcs12 as provided (at rest encryption requirement is acknowledged;
    # store as-is since we don't have KMS here, but it remains within payload only).
    payload = {
        "encryptedKeyPassword": encryptedKeyPassword,
        "pkcs12": pkcs12,
        "insertedAt": now,
        "createdVia": "insert_smime_info"
    }

    row = {
        "id": row_id,
        "gmail_account_id": gmail_account_id,
        "entity_type": "smime_info",
        "external_key": smime_id,
        "scope_key": sendAsEmail,
        "payload": payload,
        "status": "active",
        "is_default": False,
        "created_at": now,
        "updated_at": now
    }

    # Enforce constraint: at most one default active per alias (we're inserting non-default)
    settings.append(row)
    _save("gmail_settings_entities.json", settings)

    # Return resource (without sensitive fields)
    resource = {
        "id": smime_id,
        "sendAsEmail": sendAsEmail,
        "isDefault": False,
        "status": "active",
    }

    _log("success", None)
    return resource

