def set_default_smime_info(sendAsEmail, id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0088000" if __import__("os").path.isdir("./environment_mix/0088000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "set_default_smime_info"

    # --- usage log / quota helpers (best-effort; schema not provided) ---
    def _log(status, credential_id=None, gmail_account_id=None, error_code=None):
        for fname in ("gmail_request_log.json", "gmail_usage.json", "request_log.json", "usage.json", "audit_log.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                rows = _load(fname)
                now = datetime.datetime.utcnow().isoformat() + "Z"
                rows.append({
                    "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(rows)+1}",
                    "endpoint": endpoint,
                    "credential_id": credential_id,
                    "gmail_account_id": gmail_account_id,
                    "status": status,
                    "error_code": error_code,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "created_at": now,
                    "timestamp": now
                })
                _save(fname, rows)
                break

    # --- validate inputs ---
    if not isinstance(sendAsEmail, str) or not sendAsEmail.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sendAsEmail must be a non-empty string")
    if not isinstance(id, str) or not id.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    # --- resolve auth context: choose a gmail_account that can satisfy the request ---
    accounts = _load("gmail_accounts.json")
    active_accounts = [a for a in accounts if a.get("status") == "active"]
    if not active_accounts:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active Gmail account available for this operation")

    entities = _load("gmail_settings_entities.json")

    chosen = None
    for a in active_accounts:
        aid = a.get("id")
        if not aid:
            continue
        # must have send_as alias for sendAsEmail and at least one smime_info row for that alias
        has_alias = any(
            e.get("gmail_account_id") == aid and e.get("entity_type") == "send_as"
            and e.get("external_key") == sendAsEmail and e.get("status") != "deleted"
            for e in entities
        )
        if not has_alias:
            continue
        has_any_smime = any(
            e.get("gmail_account_id") == aid and e.get("entity_type") == "smime_info"
            and e.get("scope_key") == sendAsEmail and e.get("status") == "active"
            for e in entities
        )
        if not has_any_smime:
            continue
        chosen = a
        break

    if not chosen:
        # Differentiate NOT_FOUND vs UNAUTHORIZED per tool description:
        # If there are active accounts but alias/smime not present for any, treat as NOT_FOUND.
        any_alias_any_account = any(
            e.get("entity_type") == "send_as" and e.get("external_key") == sendAsEmail and e.get("status") != "deleted"
            for e in entities
        )
        if any_alias_any_account:
            _log("error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "S/MIME config or alias not found for the specified sendAsEmail")
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not authorized to access the specified mailbox alias")

    gmail_account_id = chosen.get("id")
    now = datetime.datetime.utcnow().isoformat() + "Z"

    # --- locate alias row ---
    alias_row = None
    for e in entities:
        if e.get("gmail_account_id") == gmail_account_id and e.get("entity_type") == "send_as" and e.get("external_key") == sendAsEmail and e.get("status") != "deleted":
            alias_row = e
            break
    if not alias_row:
        _log("error", gmail_account_id=gmail_account_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Send-as alias does not exist")

    # --- locate smime config for alias by immutable id ---
    target = None
    for e in entities:
        if (
            e.get("gmail_account_id") == gmail_account_id
            and e.get("entity_type") == "smime_info"
            and e.get("scope_key") == sendAsEmail
            and e.get("external_key") == id
            and e.get("status") == "active"
        ):
            target = e
            break
    if not target:
        _log("error", gmail_account_id=gmail_account_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "S/MIME config id not found for the specified sendAsEmail")

    # --- enforce constraint: exactly one active default per alias; set target default true and others false ---
    # Also enforce lifecycle transitions: smime_info statuses are in settings entity lifecycle; we're not changing status here.
    changed = False
    # Set all other active configs for alias is_default=false
    for e in entities:
        if e.get("gmail_account_id") != gmail_account_id:
            continue
        if e.get("entity_type") != "smime_info":
            continue
        if e.get("scope_key") != sendAsEmail:
            continue
        if e.get("status") != "active":
            continue

        if e is target:
            if e.get("is_default") is not True:
                e["is_default"] = True
                e["updated_at"] = now
                changed = True
        else:
            if e.get("is_default") is True:
                e["is_default"] = False
                e["updated_at"] = now
                changed = True

    if not changed:
        # idempotent success: already the default and no other defaults set
        _save("gmail_settings_entities.json", entities)
    else:
        _save("gmail_settings_entities.json", entities)

    # return updated state for alias (send_as row + all active smime_info configs for that alias)
    smime_rows = [
        e for e in entities
        if e.get("gmail_account_id") == gmail_account_id
        and e.get("entity_type") == "smime_info"
        and e.get("scope_key") == sendAsEmail
        and e.get("status") == "active"
    ]

    _log("ok", gmail_account_id=gmail_account_id)
    return {
        "sendAsEmail": sendAsEmail,
        "sendAs": alias_row,
        "smimeInfo": smime_rows
    }

