        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "topicName must be a non-empty string")
    if labelIds is not None:
        if not isinstance(labelIds, list) or any(not isinstance(x, str) or not x for x in labelIds):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "labelIds must be an array of non-empty strings when provided")
    if labelFilterAction is not None:
        if labelFilterAction not in ("include", "exclude"):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "labelFilterAction must be 'include' or 'exclude' when provided")

    accounts = _load("gmail_accounts.json")
    active_accounts = [a for a in accounts if a.get("status") == "active"]
    if not active_accounts:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active Gmail account available for this operation")
    acct = active_accounts[0]
    gmail_account_id = acct.get("id")
    if not gmail_account_id:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No valid Gmail account context")

    # validate labelIds exist for mailbox (by gmail_label_id)
    if labelIds:
        labels = _load("gmail_labels.json")
        existing = {l.get("gmail_label_id") for l in labels if l.get("gmail_account_id") == gmail_account_id and l.get("status") == "active"}
        missing = [lid for lid in labelIds if lid not in existing]
        if missing:
            _log("error", gmail_account_id=gmail_account_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "One or more labelIds do not exist for this mailbox", missingLabelIds=missing)

    entities = _load("gmail_settings_entities.json")
    now = datetime.datetime.utcnow().isoformat() + "Z"

    # upsert mail_watch with external_key='current'
    watch_row = None
    for e in entities:
        if e.get("gmail_account_id") == gmail_account_id and e.get("entity_type") == "mail_watch" and e.get("external_key") == "current":
            watch_row = e
            break

    # Generate provider-like values
    # historyId should be a string; if account has history_id, bump; else generate.
    def _bump_history(h):
        try:
            if h is None:
                raise ValueError()
            n = int(str(h))
            return str(n + 1)
        except Exception:
            return str(int(time.time() * 1000))

    new_history_id = _bump_history(acct.get("history_id"))
    expiration_ms = int((time.time() + 7 * 24 * 3600) * 1000)  # 7 days
    payload = {
        "topicName": topicName,
        "labelIds": labelIds if labelIds is not None else None,
        "labelFilterAction": labelFilterAction if labelFilterAction is not None else None,
        "historyId": new_history_id,
        "expiration": str(expiration_ms),
        "watchCreatedAt": now,
        "provider": {"watchId": f"watch_{int(time.time()*1000)}_{random.randint(1000,9999)}"}
    }

    if watch_row is None:
        # create
        new_id = f"gse_{int(time.time()*1000)}_{os.getpid()}_{len(entities)+1}"
        watch_row = {
            "id": new_id,
            "gmail_account_id": gmail_account_id,
            "entity_type": "mail_watch",
            "external_key": "current",
            "scope_key": None,
            "payload": payload,
            "status": "active",
            "is_default": None,
            "created_at": now,
            "updated_at": now
        }
        entities.append(watch_row)
    else:
        # transition: if deleted, cannot revive; if stopped/active/pending_verification, set active is allowed per lifecycle stopped->active, active->active (idempotent)
        cur = watch_row.get("status")
        if cur == "deleted":
            _log("error", gmail_account_id=gmail_account_id, error_code="INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Cannot watch a mailbox with a deleted watch record")
        if cur == "pending_verification":
            # mail_watch shouldn't be pending_verification, but if present, allow to active as a valid transition
            watch_row["status"] = "active"
        elif cur == "stopped":
            watch_row["status"] = "active"
        elif cur == "active":
            watch_row["status"] = "active"
        else:
            # unknown status
            _log("error", gmail_account_id=gmail_account_id, error_code="INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Illegal mail_watch status for watch operation", current_status=cur)

        watch_row["payload"] = payload
        watch_row["updated_at"] = now

    # Update account history_id cache
    acct["history_id"] = new_history_id
    acct["updated_at"] = now

    _save("gmail_settings_entities.json", entities)
    _save("gmail_accounts.json", accounts)

    _log("ok", gmail_account_id=gmail_account_id)
    return {
        "historyId": new_history_id,
        "expiration": str(expiration_ms)
    }

def stop_mail_watch(**_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0088000" if __import__("os").path.isdir("./environment_mix/0088000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "stop_mail_watch"

    def _log(status, credential_id=None, gmail_account_id=None, error_code=None):
        for fname in ("gmail_request_log.json", "gmail_usage.json", "request_log.json", "usage.json", "audit_log.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                rows = _load(fname)
                now = datetime.datetime.utcnow().isoformat() + "Z"
                rows.append({
                    "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(rows)+1}",
                    "endpoint": endpoint,
                    "credential_id": credential_id,
                    "gmail_account_id": gmail_account_id,
                    "status": status,
                    "error_code": error_code,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "created_at": now,
                    "timestamp": now
                })
                _save(fname, rows)
                break

    accounts = _load("gmail_accounts.json")
    active_accounts = [a for a in accounts if a.get("status") == "active"]
    if not active_accounts:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active Gmail account available for this operation")
    acct = active_accounts[0]
    gmail_account_id = acct.get("id")
    if not gmail_account_id:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No valid Gmail account context")

    entities = _load("gmail_settings_entities.json")
    now = datetime.datetime.utcnow().isoformat() + "Z"

    watch_row = None
    for e in entities:
        if e.get("gmail_account_id") == gmail_account_id and e.get("entity_type") == "mail_watch" and e.get("external_key") == "current":
            watch_row = e
            break

    if watch_row is None:
        _log("error", gmail_account_id=gmail_account_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "No mail watch exists to stop")

    cur = watch_row.get("status")
    if cur == "deleted":
        _log("error", gmail_account_id=gmail_account_id, error_code="INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Cannot stop a deleted mail watch")
    if cur == "stopped":
        # idempotent stop
        _log("ok", gmail_account_id=gmail_account_id)
        return {}

    if cur != "active":
        _log("error", gmail_account_id=gmail_account_id, error_code="INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Mail watch is not in an active state and cannot be stopped", current_status=cur)

    # transition active -> stopped, and clear provider watch metadata in payload
    payload = watch_row.get("payload") if isinstance(watch_row.get("payload"), dict) else {}
    for k in ("historyId", "expiration", "provider", "watchCreatedAt"):
        if k in payload:
            payload.pop(k, None)
    watch_row["payload"] = payload
    watch_row["status"] = "stopped"
    watch_row["updated_at"] = now

    _save("gmail_settings_entities.json", entities)

    _log("ok", gmail_account_id=gmail_account_id)
    return {}
